(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c64"]=[{"id":"00010232","register_sub_id":"101","register_pk":"198065","name":"大江家住宅大蔵","kana":"おおえけじゅうたくおおぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県日高郡みなべ町北道字濱通り309","lat":33.767289,"lng":135.320699,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積176㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0199","desc":"旧熊野街道に東面する主屋の西側東面して建つ。桁行九間、梁間五間の規模で、現状では一階を四室に間仕切るが、もとは一室の大空間であった。二階は一室で、二本の棟通り柱で牛梁を受ける。外壁は上部漆喰塗とし、高く竪板を張る。酒造の歴史を伝える大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010232"},{"id":"00007799","register_sub_id":"101","register_pk":"108780","name":"大江家住宅主屋","kana":"おおえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡みなべ町北道字濱通り309","lat":33.76749285,"lng":135.32102864,"geo_status":"db","era":"江戸後期／明治前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積321㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"30-0143","desc":"旧熊野街道に東面して建つ。間口１７ｍ、北入母屋南切妻造の主体部の南に、間口９．７ｍ、切妻造の座敷部が連続し、正面下屋庇を通す。木造つし２階建で、上部は白漆喰の大壁造とし、虫籠窓を開ける。重厚な構えのなか、繊細な出格子を備える質の高い町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007799"},{"id":"00010233","register_sub_id":"101","register_pk":"198066","name":"大江家住宅東蔵","kana":"おおえけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡みなべ町北道字濱通り309","lat":33.7672,"lng":135.320978,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0200","desc":"主屋の南西方に西面して建つ二階建の土蔵。東面は主屋の西側に広がる庭園に面しており、下部を海鼠壁に、上部を漆喰仕上とする。ほかの三面は、下部を竪板張、上部を漆喰仕上とする。家財道具の収納に使用したと伝える蔵で、敷地内の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010233"},{"id":"00012975","register_sub_id":"101","register_pk":"368054","name":"岡家住宅主屋","kana":"おかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字入郷字西上ノ山288-1","lat":34.29143333,"lng":135.55368611,"geo_status":"db","era":"明治4年／平成7年改修","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 262","desc":"紀ノ川中流南岸の集落最上部に南面して建つ。建ちの高い入母屋造桟瓦葺つし二階建の四周に下屋を廻し、大棟に本瓦葺越屋根を載せる。東に土間、西に田字形に室を配し、下手列前面を式台とするなど格式を備える。量感ある外観が集落景観に威容を誇る大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012975"},{"id":"00012978","register_sub_id":"101","register_pk":"368057","name":"岡家住宅中門","kana":"おかけじゅうたくなかもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字入郷字西上ノ山288-1","lat":34.291525,"lng":135.55356667,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、銅板葺、間口1.6m、左右袖塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 265","desc":"主屋正面西半の主庭を区切り、主屋式台南側に東面して建つ一間腕木門。切妻造銅板葺、木舞打一軒疎垂木で、吹寄せ襷桟付の井桁を二段に重ねた板扉を備える。左右に縦板張の袖塀を付し、南塀は小壁を抜く。端正なつくりで、主屋正面の構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012978"},{"id":"00012977","register_sub_id":"101","register_pk":"368056","name":"岡家住宅西蔵及び米蔵","kana":"おかけじゅうたくにしぐらおよびこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字入郷字西上ノ山288-1","lat":34.29131389,"lng":135.55375833,"geo_status":"db","era":"江戸末期／明治後期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 264","desc":"敷地西北隅に東面して建つ。西蔵は土蔵造二階建、切妻造桟瓦葺妻入で、北面の幅一間半の下屋を米蔵とし、正面に吹放し下屋を通して米蔵部分に入母屋の妻を現す。外壁は漆喰塗、正面腰海鼠壁、側背面腰縦板張。堅牢なつくりで、背面の屋敷構えを引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012977"},{"id":"00012976","register_sub_id":"101","register_pk":"368055","name":"岡家住宅部屋","kana":"おかけじゅうたくへや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字入郷字西上ノ山288-1","lat":34.29142778,"lng":135.55352778,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 263","desc":"主屋西面前方に渡廊下で接続して建つ。南北棟の入母屋造桟瓦葺平屋建で、四周に下屋を廻して下屋上を漆喰大壁とする。南北に八畳二室を並べて東南北三面に縁を廻し、南室西面に繊細な意匠の座敷飾を備える。重厚な主屋と対照的な落ち着いた佇まいの離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012976"},{"id":"00012979","register_sub_id":"101","register_pk":"368058","name":"岡家住宅門屋","kana":"おかけじゅうたくもんや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字入郷字西上ノ山288-1","lat":34.29137222,"lng":135.55365,"geo_status":"db","era":"明治4年／平成7年改修","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 266","desc":"敷地東面南寄りに建つ長屋門。南北棟の南面入母屋造桟瓦葺で、桁行中央二間に木太い軸部の門口を開き、北に納屋、南に男部屋と牛小屋を設ける。外壁は漆喰壁に与力窓を穿ち、腰を簓子下見板張とする。主屋と矩折れに並び建ち、堂々たる表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012979"},{"id":"00015081","register_sub_id":"101","register_pk":"529359","name":"岡﨑家住宅（旧栗須家住宅）石塀","kana":"おかざきけじゅうたく（きゅうくりすけじゅうたく）いしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県新宮市高田字前地上ミノ切1702","lat":33.72839722,"lng":135.90915833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、総延長76m","structure_material":"石造","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0372","desc":"屋敷地の外周、北、東、西にコ字形に廻る折曲がり総延長約七六メートルの石塀。流紋岩の川原石を幅約一・ニメートル、高さ約一・七メートルに空積の野面積みとし、東と西の各面南寄りを切欠いて出入口とする。防風を兼ねた石塀が地域の特色ある景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015081"},{"id":"00015078","register_sub_id":"101","register_pk":"529356","name":"岡﨑家住宅（旧栗須家住宅）主屋","kana":"おかざきけじゅうたく（きゅうくりすけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県新宮市高田1702","lat":33.72838611,"lng":135.90895,"geo_status":"db","era":"江戸末期／昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0369","desc":"里高田集落の中央部に位置する旧家の主屋。敷地北寄りに東面して建つ平屋建切妻造平入桟瓦葺。南に土間、北に六室配し、北東の座敷は正面広縁付とし、床は押板で古式なつくり。建ちが低く、旧杉皮葺の屋根勾配を残した民家で、地域の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015078"},{"id":"00015079","register_sub_id":"101","register_pk":"529357","name":"岡﨑家住宅（旧栗須家住宅）蔵","kana":"おかざきけじゅうたく（きゅうくりすけじゅうたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県新宮市高田1702","lat":33.72819444,"lng":135.90908611,"geo_status":"db","era":"元治2年（1865）／平成10年頃改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積22㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0370","desc":"敷地南東隅の一段高い位置に北面して建つ家財蔵。二階建切妻造妻入鉄板葺の板蔵で、正面西寄りの戸口に庇を付す。一階北寄り半間を土間の前室とする以外は各階一室の板敷で、小屋組は登梁形式とする。小規模ながら旧杉皮葺の貴重な板蔵で敷地南東景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015079"},{"id":"00015080","register_sub_id":"101","register_pk":"529358","name":"岡﨑家住宅（旧栗須家住宅）納屋","kana":"おかざきけじゅうたく（きゅうくりすけじゅうたく）なや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県新宮市高田1702","lat":33.72828056,"lng":135.90893333,"geo_status":"db","era":"明治後期／平成10年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0371","desc":"主屋の南に北面して建つ納屋。二階建切妻造平入鉄板葺で四周に下屋を付し、東面南寄りは軒を深くつくり、軒下を作業場とする。各階は東西二室に仕切り、一階は牛小屋・便所と物置、二階は各間板敷の物置で束立の和小屋を現す。敷地南の景観を形成する納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015080"},{"id":"00014915","register_sub_id":"101","register_pk":"519175","name":"岡本家住宅主屋","kana":"おかもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市高野口町九重548","lat":34.34525,"lng":135.54797222,"geo_status":"db","era":"寛政4年(1792)／令和4年改修","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積135㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0350","desc":"岩湧山南斜面の農村に所在する旧家の主屋。敷地北寄りに東面して建つ入母屋造茅葺（鉄板仮葺）で南から西へ下屋を廻らす。内部は東を土間とした六間取で、南西室の座敷は付書院のみとする簡素なつくり。軸部木太く大規模な主屋が地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014915"},{"id":"00014917","register_sub_id":"101","register_pk":"519177","name":"岡本家住宅土蔵","kana":"おかもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県橋本市高野口町九重548","lat":34.34531667,"lng":135.5479,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0352","desc":"主屋の北西に位置する家財蔵。二階建切妻造平入、置き屋根形式の桟瓦葺で、北に落棟を延ばし、東に下屋を付す。外壁は漆喰仕上で西に窓を二箇所開ける。内部は各階一室の板敷で、北に階段を設ける。重厚な外観が主屋と一体となって歴史的な景観を整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014917"},{"id":"00014918","register_sub_id":"101","register_pk":"519178","name":"岡本家住宅長屋門","kana":"おかもとけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市高野口町九重548","lat":34.34509722,"lng":135.54791111,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0353","desc":"敷地南辺に開く平屋建の長屋門。西は切妻造、東は落棟で入母屋造を接続し桟瓦葺。外壁は漆喰塗仕上で腰は押縁止の縦板張。内部は中央東寄りに高く天井を張った通路を設け、西は納屋、東は三室に仕切り牛小屋や物置とする。間口大きく旧家の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014918"},{"id":"00014916","register_sub_id":"101","register_pk":"519176","name":"岡本家住宅離れ","kana":"おかもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県橋本市高野口町九重548","lat":34.34518889,"lng":135.54782778,"geo_status":"db","era":"昭和40年頃","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0351","desc":"主屋の西に建つ平屋建切妻造桟瓦葺の離れ。東に下屋を付し、北東の渡廊下で主屋と接続する。内部は二室続きの座敷とし、南室に床と平書院を備え、東に縁を通し、部屋境には透彫の欄間を入れて飾る。主屋と一体となって南庭を囲み、敷地内の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014916"},{"id":"00002435","register_sub_id":"101","register_pk":"103425","name":"尾崎林太郎家住宅座敷","kana":"おざきりんたろうけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県海南市黒江598","lat":34.16079816,"lng":135.20453304,"geo_status":"db","era":"江戸中期／大正中期改造","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0044","desc":"主屋背面の西側にあり，平屋建，入母屋造，桟瓦葺で，北面と西面に土庇を廻す。大正中期の屋敷整備に伴い，巧みに平面が主屋と接続する。ザシキ廻りは江戸中期頃と思われ，床・棚・付書院など整った数寄屋風意匠でまとめられ，板欄間など繊細な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002435"},{"id":"00002434","register_sub_id":"101","register_pk":"103424","name":"尾崎林太郎家住宅主屋","kana":"おざきりんたろうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市黒江字南ノ町598-1","lat":34.16087048,"lng":135.20456348,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積131㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0043","desc":"尾崎家は江戸時代に大庄屋を務めた旧家で，明治時代より漆器問屋を営んだ。敷地中央に東面して建つ主屋は２階建，入母屋造，桟瓦葺である。内部構成は店舗と居室部からなり，良材を用いた丁寧なつくりで，玄関の漆塗格天井など格式の高い意匠を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002434"},{"id":"00002437","register_sub_id":"101","register_pk":"103427","name":"尾崎林太郎家住宅前蔵","kana":"おざきりんたろうけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市黒江字南ノ町598-1","lat":34.1607168,"lng":135.20463936,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積92㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0046","desc":"約５００坪の広大な屋敷地の南辺にあり，三階蔵と同時期に建てられたと思われる。三階蔵より大きく，東西棟の切妻造，桟瓦葺で，内部は二層とする。両妻側の梁で棟木を受け，太い垂木を架けた小屋構造や，妻壁の通風の丸窓など，当地域に共通する手法を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002437"},{"id":"00006213","register_sub_id":"101","register_pk":"107197","name":"加田家住宅表門","kana":"かだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.225185,"lng":135.173645,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.2m、潜戸付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0110","desc":"敷地西面のほぼ中央に建つ。棟門の両側に潜戸を付け，段違の切妻造で，桟瓦葺とする。それぞれの潜戸から矩の手に塀が延び，柱や内法長押，扉などには上質な檜や欅を用いる。長押と冠木の間に筬欄間を入れ，屋根には緩やかな起りがあり，落ち着いた外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006213"},{"id":"00006187","register_sub_id":"101","register_pk":"107171","name":"加田家住宅腰掛待合","kana":"かだけじゅうたくこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.225204,"lng":135.17406357,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積6.7㎡、雪隠付","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0106","desc":"主屋から茶室に向かう露地の途中，やや高い位置に建つ。桁行３ｍ，梁間２ｍ，切妻造，桟瓦葺。瓦は一文字瓦葺で，庇は銅板葺。正面側は下地窓を開いた腰掛，裏側には雪隠を配する。柱，桁，垂木とも丸太を使い，中塗仕上げとする。露地の構成要素として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006187"},{"id":"00006154","register_sub_id":"101","register_pk":"107138","name":"加田家住宅主屋","kana":"かだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.225281,"lng":135.173813,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0103","desc":"敷地中央に建つ。東西２０ｍ，南北２３ｍ，木造平屋建，桟瓦葺。庭園に面して客間等の座敷を雁行形に配して縁を廻す。正面中央の大玄関に入母屋の妻飾を３箇所を見せ，屋根軒下に下屋屋根を重ねるなど屋根に変化をもたせ，外観に工夫を凝らした意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006154"},{"id":"00006162","register_sub_id":"101","register_pk":"107146","name":"加田家住宅茶室","kana":"かだけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.22533,"lng":135.174057,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0105","desc":"主屋後方に庭園を挟んで建つ。南側に三畳台目茶室の不老庵，北側に八畳の広間をもつ暁月亭を配す。桟瓦葺の入母屋造及び切妻造で，深い庇を銅板葺とする。両者を廊下で繋ぎ，廊下の東側に水屋をおく。表千家と関わりのある数寄屋大工平井儀三郎の作品として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006162"},{"id":"00006161","register_sub_id":"101","register_pk":"107145","name":"加田家住宅土蔵","kana":"かだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.22532957,"lng":135.17364028,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0104","desc":"主屋正面の北寄りに建つ。桁行３間，梁間２間で，土蔵造２階建，切妻造，本瓦葺とする。２階の小屋組にはキングポストトラスを採用。正面入口や２階の窓には漆喰仕上げの塗戸を吊る。窓庇の持送りには，漆喰彫刻による渦紋の絵様をつくるなど，丁寧な仕上げ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006161"},{"id":"00006216","register_sub_id":"101","register_pk":"107200","name":"加田家住宅鳥居","kana":"かだけじゅうたくとりい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.22538766,"lng":135.17400477,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"石造、高さ2.2m、幅1.7m","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0109","desc":"敷地北東隅にある社の前面に立つ石造鳥居。間口１．７ｍ，高さ２．２ｍ。円柱を直立させ，笠木も長く直線的につくり，神明鳥居の形式とする。上質の御影石を用いて丁寧に加工しており，屋敷神の鳥居として，格式のある構えを見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006216"},{"id":"00006214","register_sub_id":"101","register_pk":"107198","name":"加田家住宅塀","kana":"かだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.22529707,"lng":135.17357164,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造、瓦葺、総延長31m","structure_material":"煉瓦造","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0111","desc":"敷地西面，表門の左右に延びる。高さ２ｍ，総延長３１ｍ，煉瓦造，桟瓦葺。外側は地元の青石（緑泥片岩）を貼って石積風に見せ，基部には御影石を貼り，重厚な趣とする。内側はモルタル塗刷毛引きとして落ち着いた仕上げとし，内外の意匠を使い分ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006214"},{"id":"00006212","register_sub_id":"101","register_pk":"107196","name":"加田家住宅社","kana":"かだけじゅうたくやしろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.225403,"lng":135.174026,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0108","desc":"敷地の北東隅，石積基壇の上に祀られる。一間社流造，見世棚造の形式で，銅板葺とする。土台に立つ角柱を長押で固め，舟肘木で桁を受ける。軒は一軒繁垂木，妻は豕扠首形式。柱，舟肘木，桁は面を大きく取り，檜の良材で丁寧につくり，技術的にも優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006212"},{"id":"00006215","register_sub_id":"101","register_pk":"107199","name":"加田家住宅露地門","kana":"かだけじゅうたくろじもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市薮ノ丁6","lat":34.225338,"lng":135.173996,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、杉皮葺、間口1.0m","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"30 － 0107","desc":"暁月亭の前面に建つ。棟門，杉皮葺。腕木で軒桁を受け，屋根は押え竹で杉皮を押え，棟には丸竹を伏せる。扉は竹簀戸を両開きに吊り込み，正統的な梅見門の形式とする。主屋前の庭園と茶室の間にある中門で，繊細な意匠とし，部材の接合などの技術に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006215"},{"id":"00012608","register_sub_id":"101","register_pk":"367902","name":"川口家住宅応接間","kana":"かわぐちけじゅうたくおうせつま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"和歌山県","address":"和歌山県有田郡有田川町大字西丹生図字畑垣内456-2","lat":34.058281,"lng":135.227203,"geo_status":"geocoded","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0246","desc":"主屋正面西隅に接続する接客棟で、東面して建つ。平屋建の切妻造洋瓦葺で、応接室と附属室からなる。外壁は大壁の色モルタル吹付けで、タイル敷テラスを備える。応接室は成の高い硝子戸や大理石製暖炉型を備える。戦後期における独立洋風応接室の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012608"},{"id":"00012607","register_sub_id":"101","register_pk":"367901","name":"川口家住宅主屋","kana":"かわぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町大字西丹生図字畑垣内456-2","lat":34.058281,"lng":135.227203,"geo_status":"geocoded","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0245","desc":"有田川南岸の平野部にある農家で、主屋は南北に長い敷地北部に南面して建つ。東西棟の切妻造で四周に下屋を廻し、丸桟瓦葺とする。東に土間半間、西に二列計六室を配し、小屋裏を物置とする。建築年代が明らかで県北部の近代和風住宅の指標として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012607"},{"id":"00012611","register_sub_id":"101","register_pk":"367905","name":"川口家住宅土塀","kana":"かわぐちけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町大字西丹生図字畑垣内456-2","lat":34.058281,"lng":135.227203,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土塀、瓦葺、延長6.1m","structure_material":"土塀","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0249","desc":"敷地東面北寄りにある敷地境の塀で、離れと納屋をつなぐ。基礎は高さ1メートルほどの切石谷積、上部の土塀は内側を漆喰塗、道路に面する外側をモルタル洗出しとする。屋根は丸桟瓦葺、軒は一文字瓦である。和洋の仕上を使い分け、内外の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012611"},{"id":"00012610","register_sub_id":"101","register_pk":"367904","name":"川口家住宅納屋","kana":"かわぐちけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡有田川町大字西丹生図字畑垣内456-2","lat":34.058281,"lng":135.227203,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造二階建、瓦葺、建築面積38㎡","structure_material":"木造二階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0248","desc":"主屋の東側、道路に東面して建つ。南北棟の入母屋造桟瓦葺で、西北二面に下屋を廻す。外壁は真壁造の漆喰塗で腰縦板張とする。内部は土間で北端を板敷とし、二階を含めて農機具の保管や蜜柑の選果などに使用した。伝統的な蜜柑農家に欠かせない附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012610"},{"id":"00012609","register_sub_id":"101","register_pk":"367903","name":"川口家住宅離れ","kana":"かわぐちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町大字西丹生図字畑垣内456-2","lat":34.058281,"lng":135.227203,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積31㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0247","desc":"敷地背面東隅に南面して建つ。寄棟造丸桟瓦葺の二階建で、南面に下屋を通す。南面以外の外壁は下見板張ペンキ塗で、二階北面に上下窓を設けるなど洋風に仕上げる。内部は和風で、二階東側の座敷に床の間を設ける。街道に面する角地にあって屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012609"},{"id":"00004386","register_sub_id":"101","register_pk":"105376","name":"河野家住宅表門","kana":"かわのけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市赤尾179","lat":34.27248418,"lng":135.37983548,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0065","desc":"敷地の南面中央からやや東寄りに開く門。間口１５尺の薬医門で，屋根は切妻造，本瓦葺とする。中央間に両開きの門扉を釣り込み，両脇間に潜り戸を設ける。木柄が太く扉板も幅広で，木製の蹴放ちが遺るのも貴重。石造の袖塀と門前の石敷が重厚な構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004386"},{"id":"00004384","register_sub_id":"101","register_pk":"105374","name":"河野家住宅主屋","kana":"かわのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県紀の川市赤尾179","lat":34.272587,"lng":135.379791,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0063","desc":"東西に長い敷地の中央に建つ。桁行７間梁間４間規模の木造平屋建で，東に土間，西に２列６室の居室を配す。屋根は入母屋造，桟瓦葺で，四周に下屋庇を巡らす。南面に突出した式台玄関は出桁を用い軒が深い。西端は８畳２室の座敷で，北面に床と書院を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004384"},{"id":"00004385","register_sub_id":"101","register_pk":"105375","name":"河野家住宅離れ座敷","kana":"かわのけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市赤尾179","lat":34.27261955,"lng":135.37961732,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0064","desc":"主屋の西に渡廊下で接続する木造平屋建，桁行５間半梁間２間半の南北棟である。屋根は入母屋造，桟瓦葺で四周に瓦葺庇を巡らす。座敷１２畳半は北面に床と棚，東に附書院を飾り，次の間１０畳は西に床を設ける。東から南に巡らせた縁にガラス障子を建て込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004385"},{"id":"00015217","register_sub_id":"101","register_pk":"530641","name":"北田家住宅土蔵","kana":"きただけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県紀の川市粉河字彌谷4734-2","lat":34.28029722,"lng":135.41054167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0378","desc":"離れ座敷の西に東面して建つ土蔵。二階建切妻造平入桟瓦葺で、正面に二箇所の戸口を開け、下屋を付す。外壁は漆喰塗仕上、正面の腰は海鼠壁。一階は北室を家財蔵、南室を道具蔵、二階は一室の物置で束立の和小屋を現す。小窓に鉄扉を付し、外観閉鎖的な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015217"},{"id":"00015216","register_sub_id":"101","register_pk":"530640","name":"北田家住宅離れ座敷","kana":"きただけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県紀の川市粉河字彌谷4734-2","lat":34.28028889,"lng":135.41065833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0377","desc":"粉河寺東方の丘陵に位置する果樹農家の来客用の離れ座敷。敷地北端に南面して建つ平屋建桟瓦葺で、西を切妻造、東を入母屋造、西面を除いた三方に下屋を廻らす。南面西端を踏込土間とした二間続きの座敷で東室に床、琵琶床、違棚、付書院を備えた瀟洒な座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015216"},{"id":"00013446","register_sub_id":"101","register_pk":"368531","name":"北山家住宅主屋","kana":"きたやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市和歌浦南二丁目1658-4","lat":34.18853333,"lng":135.16618056,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"30 － 0284","desc":"和歌浦湾北の住宅地に所在する入母屋造の東西棟で、一階に瓦葺庇を廻し、北面西端に玄関を設ける。一階は南東に大引天井の仏間八畳を配し、南面東端から便所棟が延びる。二階南東の主座敷は一間幅の平書院などに端正な造作を見せる。戦前期和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013446"},{"id":"00015068","register_sub_id":"101","register_pk":"529346","name":"旧岩橋家住宅事務所兼主屋","kana":"きゅういわはしけじゅうたくじむしょけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市黒江字南ノ町659他","lat":34.16231667,"lng":135.20586944,"geo_status":"db","era":"明治45年／昭和38年頃改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0359","desc":"黒江の川端通りに北面する旧漆器製造販売業の事務所兼主屋。二階建入母屋造平入桟瓦葺。二階外壁は黒漆喰仕上。一階は東側二間が旧の通り土間。背面の座敷棟はスギの良材を用い、床と付書院を備えた上質な続きの座敷。間口長大で地域の景観をつくる大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015068"},{"id":"00015070","register_sub_id":"101","register_pk":"529348","name":"旧岩橋家住宅土蔵","kana":"きゅういわはしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市黒江字南ノ町659他","lat":34.16221111,"lng":135.20598333,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0361","desc":"敷地南東隅に建つ漆器収納蔵。土蔵造二階建切妻造桟瓦葺で西棟東端に南北棟が接続し全体は矩折れの平面。外壁漆喰塗で軒に鉢巻を廻し上部竪板張。二階は板敷の一室で小屋組は東西棟は登梁形式、南北棟は束立の和小屋。事務所兼主屋と一体で敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015070"},{"id":"00015069","register_sub_id":"101","register_pk":"529347","name":"旧岩橋家住宅煉瓦蔵","kana":"きゅういわはしけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市黒江字南ノ町659他","lat":34.16229722,"lng":135.20574444,"geo_status":"db","era":"明治後期／昭和38年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積51㎡","structure_material":"煉瓦造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0360","desc":"主屋の西に建つ家財蔵。煉瓦造二階建切妻造で東面に戸口を開き主屋に接続。壁体はイギリス積で外壁は黒漆喰仕上とし軒に鉢巻を廻し、腰は緑釉タイル貼。各階板敷で小屋組は束立の和小屋と登梁形式の併用。煉瓦蔵を土蔵風にみせた重厚な外観が地域景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015069"},{"id":"00014914","register_sub_id":"101","register_pk":"519174","name":"旧大石家住宅主屋","kana":"きゅうおおいしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市下津町塩津字鈴山166","lat":34.133875,"lng":135.16628889,"geo_status":"db","era":"江戸末期／令和4年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0349","desc":"塩津港で廻船業を営んだ商家の主屋。道に面する切妻造桟瓦葺で建ちの低い二階建。一階を縦板壁、二階を漆喰塗、表は出格子を設ける。内部は南東を土間とする四つ間取りで、表側奥を座敷とし間口半間の床の間を設ける。塩津港海沿いの歴史的景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014914"},{"id":"00013176","register_sub_id":"101","register_pk":"368305","name":"旧神田家別邸（稲村亭）","kana":"きゅうかんだけべってい（とうそんてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県東牟婁郡串本町串本字寺前生879-1","lat":33.46971111,"lng":135.77845833,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0279","desc":"紀伊半島南端の串本町を代表する商家の別邸である。敷地中央に南面して建つ。東を土間、西を床上部とする農家型の平面で、桟瓦葺の大屋根を載せる。稲村海岸に流れ着いた巨木と伝わる目の詰んだ柾目のスギ材を用いて造作し、端正な造りで上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013176"},{"id":"00013879","register_sub_id":"101","register_pk":"507837","name":"旧谷畑家住宅（こざがわ）主屋","kana":"きゅうたにはたけじゅうたく（こざがわ）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県東牟婁郡串本町西向字カジヤ谷78-1","lat":33.52262222,"lng":135.81956389,"geo_status":"db","era":"昭和29年／平成31年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積175㎡","structure_material":"木造2階一部平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0316","desc":"古座川の河口に位置。Ｔ字形平面の二階建の西と北東に平屋を張出す。入母屋造桟瓦葺で一、二階とも銅板葺の庇を廻し、出桁造で吹寄の垂木を配る。たちが高く庭や川に面する西・南面はガラス戸を建て眺望を誇る。良材を用い、丁寧な造作になる近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013879"},{"id":"00013448","register_sub_id":"101","register_pk":"368533","name":"旧チャップマン邸石段及び石垣","kana":"きゅうちゃっぷまんていいしだんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県新宮市丹鶴一丁目7677-2","lat":33.72810278,"lng":135.99280556,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造、延長50m","structure_material":"石造","registered":"2020.08.17(令和2.08.17)","register_no":"30 － 0286","desc":"敷地の南東面を区切る石垣及び前面道路からの通路となる石段。石垣は花崗斑岩の間知石を谷積に築き、東端に井戸のためにアーチを組んだ石室を設ける。石段は玄関までの路面に野面石を敷詰め、石張の門柱を入口脇に立てる。主屋と共に西村伊作の作風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013448"},{"id":"00013447","register_sub_id":"101","register_pk":"368532","name":"旧チャップマン邸主屋","kana":"きゅうちゃっぷまんていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県新宮市丹鶴一丁目7677-2","lat":33.72824167,"lng":135.99283333,"geo_status":"db","era":"大正15年／平成30年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、スレート葺、建築面積128㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"30 － 0285","desc":"木造二階建、スレート葺の宣教師館。南面東半は二階をやや張出して切妻をみせ、一階は半八角形平面の出窓が突出するなど、変化に富んだ外観をつくる。一階に南側の庭園に面して居間と事務室、二階に学習室や寝室を配す。設計者西村伊作の作風の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013447"},{"id":"00013752","register_sub_id":"101","register_pk":"505311","name":"旧土谷家住宅主屋（こむぎ処マルキ）","kana":"きゅうつちやけじゅうたくおもや（こむぎどころまるき）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市紀三井寺1102","lat":34.18395833,"lng":135.18834444,"geo_status":"db","era":"江戸末期／平成29年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 299","desc":"紀三井寺参道の南で、熊野街道に東面する。つし二階建入母屋造妻入で上屋を三間の錣葺に見せるが梁は間口一杯の四間に架ける。正面一階に出格子を付け本瓦葺の庇を架ける。二階は黒漆喰塗に虫籠窓を並べ、白漆喰塗の妻壁と対比をなす。重厚な外観を持つ町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013752"},{"id":"00011392","register_sub_id":"101","register_pk":"209229","name":"旧戸田家住宅網工場","kana":"きゅうとだけじゅうたくあみこうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027445,"lng":135.173041,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0220","desc":"主屋の北側に妻を見せて建つ桁行二八メートルの長大な建物。一・二階とも窓を多く取り、一階は土間として三室に区切り、奥の一室は土壁で囲う。二階は一室の作業場とする。小屋は和小屋で、水平梁と登梁を混用する。製網用に広い内部空間をとった工場建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011392"},{"id":"00011391","register_sub_id":"101","register_pk":"209228","name":"旧戸田家住宅隠居棟","kana":"きゅうとだけじゅうたくいんきょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027316,"lng":135.173081,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0219","desc":"主屋の背面側に建つ独立棟。主として保太郎の弟が起居したと伝える。緩やかな起り屋根の入母屋造平屋建で、南以外の三面に銅板葺の庇を廻らす。西面戸口を両開板戸とし、半間土間を介して四畳と六畳の二室を並べる。庇を扇垂木とし、軽快な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011391"},{"id":"00011390","register_sub_id":"101","register_pk":"209227","name":"旧戸田家住宅大座敷棟","kana":"きゅうとだけじゅうたくおおざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027338,"lng":135.173202,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0218","desc":"敷地の東北隅に建つ。木造平屋建、入母屋造桟瓦葺で、網工場に接する西面以外は庇を付す。庭に面した南・東の二面は庇軒先を銅板葺として軽快に見せる。内部は一〇畳二室と四畳を配し、庭側に縁を廻らす。檜の良材を用い、上質な意匠でまとめた客座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011390"},{"id":"00011389","register_sub_id":"101","register_pk":"209226","name":"旧戸田家住宅主屋","kana":"きゅうとだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027425,"lng":135.17291,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0217","desc":"近世から製網業を営んだ家の主屋。通りに西面し、南側に土間を取って北に床上部四室を配し、土間背面には台所を突出させる。二階は土間上の一部を吹き抜けとし、西北隅八畳は棹縁天井を折り上げる。外観も二階出格子窓下部を漆喰で持ち出すなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011389"},{"id":"00011393","register_sub_id":"101","register_pk":"209230","name":"旧戸田家住宅西蔵","kana":"きゅうとだけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027354,"lng":135.172834,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0221","desc":"主屋南に建ち、街路に妻面を見せる。桁行梁間とも五・九メートルの正方形平面で、本瓦葺。基礎石の上に土台を敷いて半間毎に柱を立てる。内部は一階が竪板張、二階は漆喰塗とする。外壁は主屋側を海鼠壁とする他は竪板張とし、上部は漆喰塗で鉢巻を廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011393"},{"id":"00011394","register_sub_id":"101","register_pk":"209231","name":"旧戸田家住宅東蔵","kana":"きゅうとだけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1347他","lat":34.027314,"lng":135.172909,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"30－0222","desc":"西蔵に並んで建つ。外壁の意匠を西蔵とほぼ同一にするが、桁行がやや長い長方形平面で、計画寸法も桁行梁間で違えている。北面と東面は下部を海鼠壁とするが、それぞれ四半張と芋張として意匠を変えている。家財蔵と伝え、漁業で栄えた地域の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011394"},{"id":"00012790","register_sub_id":"101","register_pk":"367693","name":"旧野田家住宅主屋","kana":"きゅうのだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡美浜町大字三尾字後出482","lat":33.89364139,"lng":135.13334167,"geo_status":"db","era":"昭和9年頃／平成29年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積115㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 256","desc":"町西部の旧三尾村にある洋風住宅。寄棟造洋瓦葺の二階建、外壁下見板張ペンキ塗で、南面中央の玄関ポーチは円柱やアーチ状の垂壁を用いて洋風意匠を強調する。内部はホール中心の洋式の空間構成に和室を混在する。カナダ移民で知られる三尾地区の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012790"},{"id":"00012791","register_sub_id":"101","register_pk":"367694","name":"旧野田家住宅門及び塀","kana":"きゅうのだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡美浜町大字三尾字後出482","lat":33.89364139,"lng":135.13334167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 コンクリート造、間口1.8m 塀 コンクリート造、総延長23m","structure_material":"門 コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 257","desc":"敷地東面の南端に開く門と左右に延びる塀。コンクリート造のモルタル洗出し仕上。門は角形の門柱を間口一・八メートルで立て、頂部を宝形につくる 。塀は下端を土台状、頂部を笠木状につくりだし、壁面に柱形を表す。洋風住宅の表構えを瀟洒に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012791"},{"id":"00000887","register_sub_id":"101","register_pk":"101877","name":"旧橋本本陣池永家住宅表門","kana":"きゅうはしもとほんじんいけながけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本2-80-1","lat":34.3163159,"lng":135.61474513,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造四脚門，瓦葺，建築面積5.1㎡","structure_material":"木造四脚門","registered":"1998.10.09(平成10.10.09)","register_no":"30 － 0019","desc":"街道に面して主屋と土蔵に挟まれて建ち，本陣である離座敷への通路を構成している。形式は四脚門で，潜戸と脇壁に与力窓がつく。主屋，土蔵とともに橋本の古い町並みを今日に伝えるものとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000887"},{"id":"00000885","register_sub_id":"101","register_pk":"101875","name":"旧橋本本陣池永家住宅主屋","kana":"きゅうはしもとほんじんいけながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本2-80-1","lat":34.31631396,"lng":135.61483846,"geo_status":"db","era":"享保16以前","year":1731,"year_source":"db","year_min":1731,"year_max":1731,"year_label":null,"structure":"木造２階建，瓦葺，建築面積150㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"30 － 0017","desc":"街道に面し，紀ノ川を背にした敷地に建つ。つし２階をもつ入母屋造，平入の町家で，屋根は本瓦葺であるが，当初茅葺であったものを宝暦２年に葺き替えたことが鬼瓦銘から知られる。建立年代の判明している町屋としては和歌山県下最古のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000885"},{"id":"00000888","register_sub_id":"101","register_pk":"101878","name":"旧橋本本陣池永家住宅土蔵","kana":"きゅうはしもとほんじんいけながけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本2-80-1","lat":34.31626632,"lng":135.61470235,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造２階建，瓦葺，建築面積51㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"30 － 0020","desc":"紀ノ川に面した交通の要衝であり，江戸時代を通じて宿駅，商業地として栄えた橋本宿の，伊勢（大和）街道に面して平を見せて建つ土蔵である。一部に改造が見られるものの，街路に面した白壁が目を引く建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000888"},{"id":"00000886","register_sub_id":"101","register_pk":"101876","name":"旧橋本本陣池永家住宅離座敷","kana":"きゅうはしもとほんじんいけながけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本2-80-1","lat":34.31611174,"lng":135.61479179,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建，瓦葺，建築面積96㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"30 － 0018","desc":"敷地の奥側，紀ノ川に面した位置に建つ。北の間，上之間など主要４室と，渡り廊下で結ばれた湯殿・雪隠などからなり，主屋とは別の渡り廊下で連絡されている。資料等から本陣として用いられていたことが明らかで，内装の質も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000886"},{"id":"00009367","register_sub_id":"101","register_pk":"194160","name":"旧松井家別邸（がんこ六三園）裏門","kana":"きゅうまついけべってい（がんころくさんえん）うらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21421942,"lng":135.16811517,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造、間口3.4m","structure_material":"鉄筋コンクリート造","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0168","desc":"敷地南面、浴室棟の西側に建つ。鉄筋コンクリート造で間口三・四メートル、両側に門柱が立ち、間口一・二メートルの戸口に板戸を開く。門柱間を欠円アーチで繋ぎ、戸口に枠と頂部のキーストーンを象る。簡略化された洋風意匠が独自の雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009367"},{"id":"00009360","register_sub_id":"101","register_pk":"194153","name":"旧松井家別邸（がんこ六三園）表門","kana":"きゅうまついけべってい（がんころくさんえん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21454293,"lng":135.16824374,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0161","desc":"敷地東面北寄りに建つ長屋門。木造平屋建、桁行九・六メートル梁間三・八メートル、入母屋造本瓦葺北二間を部屋、南三間を通路とし、引分けの板戸を建込む。外壁は漆喰仕上の真壁とし、腰を簓子下見板及びスギ一枚板張とする。広大な屋敷地の正面を飾る正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009360"},{"id":"00009362","register_sub_id":"101","register_pk":"194155","name":"旧松井家別邸（がんこ六三園）北土蔵","kana":"きゅうまついけべってい（がんころくさんえん）きたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21469628,"lng":135.16762858,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0163","desc":"敷地の北西隅、南蔵の北側に並び建つ。土蔵造二階建、桁行六・七メートル梁間四・八メートル、切妻造本瓦葺で、南面東寄りに戸口を開ける。小屋はトラス組。外壁は漆喰塗で鉢巻を廻す。小路側の北面は腰を竪板張、基礎は切石張とし、落着いた景観を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009362"},{"id":"00009364","register_sub_id":"101","register_pk":"194157","name":"旧松井家別邸（がんこ六三園）給水塔","kana":"きゅうまついけべってい（がんころくさんえん）きゅうすいとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.2147139,"lng":135.16771604,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、鉄板葺、建築面積18㎡","structure_material":"煉瓦造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0165","desc":"主屋の北側に建つ。煉瓦造、片流れ屋根で、小屋組は梁間方向に垂木をわたす。軒にコー二スを廻し、二階各面に上下窓を二箇所設け、その上下端にタイルで白色バンドを入れる。和風建築群の中にあって洋風意匠の近代設備を大胆に取入れ、特徴的な景観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009364"},{"id":"00009359","register_sub_id":"101","register_pk":"194152","name":"旧松井家別邸（がんこ六三園）主屋","kana":"きゅうまついけべってい（がんころくさんえん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21452236,"lng":135.16786281,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部銅板葺、建築面積357㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0160","desc":"敷地中央に建つ。東面し、式台玄関を持つ玄関棟の南側に座敷棟、西奥に二階棟を接続する。建築面積三五七平方メートル。各棟とも庭園の眺望を考慮し、南面を中心に縁を廻し、窓を大きく開ける。規模が大きく、全体を落ち着いた意匠で統一した和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009359"},{"id":"00009361","register_sub_id":"101","register_pk":"194154","name":"旧松井家別邸（がんこ六三園）茶室","kana":"きゅうまついけべってい（がんころくさんえん）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21453913,"lng":135.16803056,"geo_status":"db","era":"大正後期／平成12年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺一部銅板葺及び檜皮葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0162","desc":"表門と主屋の間に建ち、南に庭園を望む。東西棟の切妻造桟瓦葺一部銅板葺の主体部周囲に檜皮葺の土庇や入母屋造の角屋などを張出し複雑な外観とする。内部は四畳半本勝手の上座床とし、西に控えの間、北に水屋と出入口を設ける。開放的な近代の茶室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009361"},{"id":"00009368","register_sub_id":"101","register_pk":"194161","name":"旧松井家別邸（がんこ六三園）土塀","kana":"きゅうまついけべってい（がんころくさんえん）どべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21419389,"lng":135.16790287,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土塀、瓦葺、総延長91m","structure_material":"土塀","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0169","desc":"長屋門南妻から敷地南面及び西面まで折曲がりに延びる。高さ約二メートル、桟瓦葺で、軒下を漆喰塗、外壁は土壁に弁柄色の骨材を吹付け、赤味を帯びる。腰は砂岩質の切石を二段重ね、基礎に地元産の青石を積む。伝統的な彩色が施され屋敷の外観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009368"},{"id":"00009366","register_sub_id":"101","register_pk":"194159","name":"旧松井家別邸（がんこ六三園）便所","kana":"きゅうまついけべってい（がんころくさんえん）べんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21448619,"lng":135.16813562,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺一部檜皮葺、建築面積7.6㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0167","desc":"茶室の南東に建つ。桁行二・六メートル梁間二・八メートル、切妻造桟瓦葺で軒先を檜皮葺とする葺。北妻の出入口に杉皮葺の庇を付ける。外壁は黄大津、腰はモルタル仕上げとし、各面に様々な形の下地窓を開ける。手の込んだ数寄屋造として庭園空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009366"},{"id":"00009363","register_sub_id":"101","register_pk":"194156","name":"旧松井家別邸（がんこ六三園）南土蔵","kana":"きゅうまついけべってい（がんころくさんえん）みなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21463491,"lng":135.16762048,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造、瓦葺、建築面積18㎡","structure_material":"土蔵造","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0164","desc":"北蔵の南に建ち、土蔵造平屋建、桁行四・八メートル梁間三・八メートル、切妻造本瓦葺である。東面に戸口を開き、二階の三面に窓を穿つ。軒下に鉢巻を廻し、外壁は漆喰塗で鉢巻を廻し、小屋はトラス組。小規模ながら主屋、北蔵とともに屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009363"},{"id":"00009365","register_sub_id":"101","register_pk":"194158","name":"旧松井家別邸（がんこ六三園）浴室棟","kana":"きゅうまついけべってい（がんころくさんえん）よくしつとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-3-22","lat":34.21422315,"lng":135.1681462,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造平屋建、建築面積18㎡","structure_material":"煉瓦造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"30 － 0166","desc":"敷地の南東、南面道路沿い建つ。建築面積一七・六平方メートル、煉瓦造で陸屋根のスラブを鉄筋コンクリート造とする。外壁頂部にパラペットをつくり、コーニスを廻す。内部は浴室や脱衣室とする。外観を円弧などの幾何意匠で構成し、当時の意匠の傾向を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009365"},{"id":"00010499","register_sub_id":"101","register_pk":"199447","name":"旧南方家住宅井戸屋形","kana":"きゅうみなかたけじゅうたくいどやかた","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県田辺市中屋敷町36-1","lat":33.73081,"lng":135.377822,"geo_status":"db","era":"明治中期／平成17改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0212","desc":"主屋の南東方向、台所の傍らに建ち、外台所とも呼ばれていたという。建ちが低く、屋根は招造桟瓦葺とする。平面は、西から井戸、土間、床上部とし、それぞれ土壁で仕切られる。中央の土間にはかつて竈が設置されていた。往時の生活の様子を現在に伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010499"},{"id":"00010496","register_sub_id":"101","register_pk":"199444","name":"旧南方家住宅主屋","kana":"きゅうみなかたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県田辺市中屋敷町36-1","lat":33.730888,"lng":135.3778,"geo_status":"db","era":"明治後期／平成17改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積71㎡","structure_material":"木造2階一部平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0209","desc":"田辺旧城下の和歌山藩与力屋敷跡地に建つ民家。南方熊楠が大正五年に移り住み、晩年を過ごした住居として知られる。木造二階建で上下階とも二室の座敷を並べる。外壁は軒下小壁を漆喰塗とするほかは焼杉板の下見板張としており、素朴な風貌を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010496"},{"id":"00010497","register_sub_id":"101","register_pk":"199445","name":"旧南方家住宅書斎","kana":"きゅうみなかたけじゅうたくしょさい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県田辺市中屋敷町36-1","lat":33.730863,"lng":135.37764,"geo_status":"db","era":"大正4／大正5移築・平成17改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0210","desc":"敷地の西方に建つ小規模な建築で、熊楠自筆の敷地図には「研究室」と記される。切妻造桟瓦葺で、八畳一室の東西に縁を設けて開放的につくり、漆喰塗の外壁は腰を竪板張とする。現在は、粘菌などの研究に没頭した熊楠存命中の研究室の状況を再現して展示する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010497"},{"id":"00010498","register_sub_id":"101","register_pk":"199446","name":"旧南方家住宅土蔵","kana":"きゅうみなかたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県田辺市中屋敷町36-1","lat":33.730949,"lng":135.377651,"geo_status":"db","era":"明治中期／平成17改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0211","desc":"書斎の北方に主屋と平行して南北棟で建つ。土蔵造二階建で、小屋組は登梁形式、屋根は本瓦葺とする。外壁は焼杉板の竪板張である。熊楠存命中は、一階を書庫に、二階を物置に使っていたと伝える。他の建物と同様の外観仕様になり、屋敷内の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010498"},{"id":"00009658","register_sub_id":"101","register_pk":"194654","name":"木綿家住宅主屋","kana":"きわたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-2-28","lat":34.21533135,"lng":135.17318519,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"30 － 0171","desc":"市街地の宅地に南面し、木造平屋建、入母屋造桟瓦葺である。東端に玄関を構え、西脇の洋風応接間は切妻造スパニッシュ瓦葺とし、二連アーチ窓を設ける。西半は庭に面して和室を並べ縁を廻らせる。和洋両室とも意匠に優れる、戦前の上質な洋間付住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009658"},{"id":"00009660","register_sub_id":"101","register_pk":"194656","name":"木綿家住宅土蔵","kana":"きわたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-2-28","lat":34.21550743,"lng":135.17303767,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"30 － 0173","desc":"離れ後方に東西棟で建ち、桁行七・三メートル梁間四・六メートル、土蔵造二階建、切妻造桟瓦葺である。南面入口に大きな鉄扉を両開きとし、上部の天井廻りに洋風の蛇腹を廻らせる。外壁漆喰塗で東妻面の上下階に、独特な繰形の持送りを付した庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009660"},{"id":"00009659","register_sub_id":"101","register_pk":"194655","name":"木綿家住宅離れ","kana":"きわたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-2-28","lat":34.21545746,"lng":135.17309953,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積84㎡","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"30 － 0172","desc":"主屋後方に中庭を介して建ち、木造平屋一部二階建で、屋根は桟瓦の錣葺とする。東側に和室二室、西端に六畳茶室を配する。茶室では、皮付丸太や面皮柱、竹棹縁を用いるなど数寄屋風を基調とし、また二階の軒は垂木を扇に配る。洗練されたつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009659"},{"id":"00009661","register_sub_id":"101","register_pk":"194657","name":"木綿家住宅門及び塀","kana":"きわたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-2-28","lat":34.21524316,"lng":135.17333556,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"門 木造、瓦葺、間口3.8m 塀 煉瓦造、瓦葺、総延長21m","structure_material":"門 木造","registered":"2013.06.21(平成25.06.21)","register_no":"30 － 0174","desc":"主屋玄関正面に構える門と、左右に折曲がりにのびる塀。門は一間薬医門、切妻造桟瓦葺で、左右に落棟の脇門を開く。塀の腰は花崗岩張、壁はモルタル掻落し仕上げで、桟瓦葺とする。門の両側で円弧状に曲げて穏やかな印象を持たせ、良質な宅地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009661"},{"id":"00004812","register_sub_id":"101","register_pk":"105802","name":"楠本家住宅主屋","kana":"くすもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市清水123","lat":34.30844424,"lng":135.604019,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"30 － 0073","desc":"旧高野街道に北面して建つ。周囲に下屋を廻した入母屋造，桟瓦葺のつし２階建で，内部は東方を土間とした四間取形式とする。外壁は黒漆喰仕上げの大壁とし，垂木までを塗込めた防火的なつくりが特徴的で，つし２階正面両隅の円弧状付柱の意匠にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004812"},{"id":"00004814","register_sub_id":"101","register_pk":"105804","name":"楠本家住宅土蔵","kana":"くすもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市清水123","lat":34.308262,"lng":135.60405,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"30 － 0075","desc":"離座敷の東南方に位置し，南北棟で建つ。桁行３間半梁間２間，切妻造，桟瓦葺，妻入の２階建土蔵で，北妻面の西寄りに縁取り付きの開口をとり，片引の大戸形式の戸口を設ける。２階の西面と南面に小さな窓を開ける。屋敷構えに欠くことのできない建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004814"},{"id":"00004815","register_sub_id":"101","register_pk":"105805","name":"楠本家住宅納屋","kana":"くすもとけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市清水123","lat":34.30822086,"lng":135.603943,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"30 － 0076","desc":"敷地南辺一杯に東西棟で建つ。桁行１２間半梁行２間，入母屋造，桟瓦葺の平屋建で，小路に面する南面東寄りに門口をとり，その東側を薪小屋，西側を３室に分ける。外壁は北面の真壁造に対し，南面は大壁造で，腰縦板張，軒裏を塗込めて小路沿い景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004815"},{"id":"00004813","register_sub_id":"101","register_pk":"105803","name":"楠本家住宅離座敷","kana":"くすもとけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県橋本市清水123","lat":34.3083159,"lng":135.603973,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"30 － 0074","desc":"主屋の南方に位置する。６畳・床付８畳・６畳をＬ字形に配した平面をもち，屋根は主屋側の北妻を入母屋造，南妻を寄棟造，東妻を切妻造に納め，東・北・西の３面に縁を廻らす。外部は軒裏を塗込た丁寧なつくりで，内部も吟味された良材を用いた上質なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004813"},{"id":"00013871","register_sub_id":"101","register_pk":"507829","name":"久保田家住宅主屋","kana":"くぼたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原字中ノ坪165","lat":33.90471389,"lng":135.16278889,"geo_status":"db","era":"文化5年(1808)／明治後期増築","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0308","desc":"熊野街道の宿場小松原に位置。入母屋造本瓦葺で軒を深く葺き下ろす重厚な外観を持つ。北西に二階建土蔵造のオクナンドが接続。内部は東を土間とし、西の床上部を二列三室配する奥深い構成。各室は差鴨居で固めるが溝は三本で古式。街道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013871"},{"id":"00013872","register_sub_id":"101","register_pk":"507830","name":"久保田家住宅新座敷","kana":"くぼたけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原字中ノ坪165","lat":33.90485556,"lng":135.16276667,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積136㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0309","desc":"街道の東に接し、南は廊下を介して主屋に接続。平屋建入母屋造桟瓦葺。南面し、東西に三室並べ、南面西端に小玄関を設ける。東二室は続き間の書院座敷で正側面に縁を廻す。良質の栂材を用い、色ガラスの障子戸等に当時の流行を示す。主屋と一体で景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013872"},{"id":"00013873","register_sub_id":"101","register_pk":"507831","name":"久保田家住宅長屋門","kana":"くぼたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原字中ノ坪165","lat":33.90448611,"lng":135.16287222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0310","desc":"熊野街道から引込む敷地南辺の小道に面して建つ。平屋建切妻造本瓦葺。西一間半を門口、東二間半を蔵とする長屋門。門口は楣で固め板戸片引を建てる。背面は軒を出桁造として漆喰で塗込める。蔵は背面中央に戸前を設ける。旧家の格式ある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013873"},{"id":"00013874","register_sub_id":"101","register_pk":"507832","name":"久保田家住宅塀","kana":"くぼたけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原字中ノ坪165","lat":33.90446667,"lng":135.16268889,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"鉄筋コンクリート造、総延長27m","structure_material":"鉄筋コンクリート造","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0311","desc":"敷地の西及び南辺を区画する鉄筋コンクリート造の塀。約一・五メートル間隔で柱形を付け、柱間は隅を円弧状に欠いた額縁を造り、内部をドイツ壁風のモルタルで仕上げる。腰壁、柱形、笠木は洗出仕上。簡素な洋風基調の塀だが屋敷構えに整った印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013874"},{"id":"00005400","register_sub_id":"101","register_pk":"106388","name":"小西家住宅主屋","kana":"こにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市新高町64","lat":34.203735,"lng":135.16687,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"30 － 0089","desc":"北面に入母屋造の表玄関をもつ桟瓦葺の２階建住宅。全体を和風意匠で纏め，基本的に中廊下型の平面構成で，玄関脇に洋風の応接間を配し，１階，２階とも敷地南の庭に面して座敷を配する。造作は上質の材をふんだんに用い，繊細につくる。昭和初期住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005400"},{"id":"00005401","register_sub_id":"101","register_pk":"106389","name":"小西家住宅土蔵","kana":"こにしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市新高町64","lat":34.203846,"lng":135.16684,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"30 － 0090","desc":"北辺が街路に接した敷地北西隅に建つ。桁行２間，梁間１間半，東西棟で切妻造，本瓦葺の土蔵造２階建。南面に出入口を設け，外壁は漆喰塗で，窓庇まで漆喰塗とし，軒廻りに鉢巻を廻すなど，丁寧なつくりの土蔵。伝統的な街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005401"},{"id":"00005402","register_sub_id":"101","register_pk":"106390","name":"小西家住宅門及び塀","kana":"こにしけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市新高町64","lat":34.20383937,"lng":135.16689336,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"門 木造、瓦葺及び銅板葺、間口3.4m、塀 木造、瓦葺、延長12m","structure_material":"門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"30 － 0091","desc":"主屋北面にある門は，背面に控柱を設けた棟門形式で，内法長押と冠木の間を筬欄間で飾る。屋根は切妻造であるが，棟廻りを瓦葺，周囲を銅板葺とし，西の潜戸，東の脇壁にも同形の屋根を架ける。この東西に真壁造の塀が延び，敷地北辺の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005402"},{"id":"00003907","register_sub_id":"101","register_pk":"104897","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市古佐田1-237、247","lat":34.317078,"lng":135.612717,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"30 － 0054","desc":"集落中央を東西に貫く通りの西端突当りに位置する。入母屋造，平入の町家で，下手に通り土間，床上部は田の字形に４室を配し，背後に角屋を延ばし炊事場とする。１階正面に繊細な格子を入れ，塗込のつし２階正面に虫籠窓を開け，町並の核として外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003907"},{"id":"00003908","register_sub_id":"101","register_pk":"104898","name":"小林家住宅土蔵","kana":"こばやしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市古佐田1-237、247","lat":34.31714199,"lng":135.61260671,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"30 － 0055","desc":"主屋背後に建つ。棟高，軒高の異なる平入３棟が南北に連なる形式で，最も高い北端につし２階を設ける。内部は南端を土間，その北に床を張り家財や穀類の貯蔵に使われた。特異な屋根の納まり，腰部海鼠壁による変化に富む外観は，屋敷背面の景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003908"},{"id":"00010490","register_sub_id":"101","register_pk":"199438","name":"坂部家住宅乾蔵","kana":"さかべけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市府中875","lat":34.262958,"lng":135.229733,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0203","desc":"敷地の北西隅に建つ土蔵造二階建で、南北棟の切妻造とする。屋根は置屋根形式で、本瓦葺である。外部の壁は漆喰塗、腰は竪板張とする。もとは二階に食器類が保管され、家財道具を納める蔵であった。角地に建ち、農村部の歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010490"},{"id":"00005350","register_sub_id":"101","register_pk":"106338","name":"坂部家住宅主屋","kana":"さかべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市府中875","lat":34.262875,"lng":135.229782,"geo_status":"db","era":"江戸後期／文久2移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0084","desc":"市東部，紀ノ川右岸に位置する。桁行９間，梁間７間の規模，入母屋造，本瓦葺，平入の平屋建とし，下屋を四周に廻らし，黒漆喰で塗り込めた上部の壁には平側に木瓜形の虫籠窓を穿つ。大規模な農家建築で，集落の中で際立った存在となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005350"},{"id":"00010489","register_sub_id":"101","register_pk":"199437","name":"坂部家住宅離座敷","kana":"さかべけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市府中875","lat":34.262793,"lng":135.229958,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0202","desc":"市東部、紀ノ川右岸に所在し、主屋の東に渡廊下を介して接続する。小規模な離れで、六畳と四畳半の二室を南北に並べ、六畳の南に切目縁を、四畳半の北から西に榑縁を廻す。四畳半には床、六畳には地袋を設け、要所に杉丸太などを用い、丁寧な造作となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010489"},{"id":"00010491","register_sub_id":"101","register_pk":"199439","name":"坂部家住宅門長屋","kana":"さかべけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市府中875","lat":34.262774,"lng":135.229669,"geo_status":"db","era":"江戸末期／平成18改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0204","desc":"敷地の西側南寄りに西面して建つ。長屋門形式の建物で、入母屋造本瓦葺とし、東面の一部に下屋を付す。門口の北にウシベヤ、南にウマベヤほか四室を並べる。ウマベヤに馬とどめの柵を残す希少な遺構であり、旧家の正門として景観上も重要な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010491"},{"id":"00015082","register_sub_id":"101","register_pk":"529360","name":"﨑山家住宅主屋","kana":"さきやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1311","lat":34.02609444,"lng":135.172375,"geo_status":"db","era":"明治後期／昭和40年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0373","desc":"旧広村中心部にある商家の主屋。通りに東面するつし二階建入母屋造本瓦葺。一階南寄りを戸口とし北に三連の出格子を構え、二階は軒を出桁とし袖壁を付す。内部は通り土間の南北に部屋を並べ北西隅を主座敷とする。建ちが低く、重厚な外観が歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015082"},{"id":"00012446","register_sub_id":"101","register_pk":"531770","name":"笹野家住宅表門及び塀","kana":"ささのけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市薗字新町731他","lat":33.88603889,"lng":135.1561,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門 木造、瓦葺、間口2m 塀 木造、瓦葺、総延長14m","structure_material":"表門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"30-237","desc":"表門は通りからやや奥に建つ棟門で、切妻造桟瓦葺で楣上に小庇を設ける。門口は引違い格子戸、内両開き板戸を建込む。塀は表門の左右に延びる真壁造の高塀で、斜めに曲がる隅柱を菱形とするなど凝ったつくりである。屋敷の表構えを格調高く演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012446"},{"id":"00012443","register_sub_id":"101","register_pk":"531767","name":"笹野家住宅主屋","kana":"ささのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市薗字新町731他","lat":33.88588889,"lng":135.1561,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積282㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"30-234","desc":"中心市街地の南西部にある。二階建の桟瓦葺で、北に玄関を開き、右脇に応接間、南に座敷二室を配し、二階に座敷二室や茶室をもつ。巧みな廊下の構成や応接間の洋風意匠、二階座敷の矩折れに配した床脇など、随所に近代の手法を取込んだ昭和前期の和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012443"},{"id":"00012445","register_sub_id":"101","register_pk":"531769","name":"笹野家住宅土蔵","kana":"ささのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市薗字新町731他","lat":33.88601111,"lng":135.156,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"30-236","desc":"主屋の前方、通りに面して建つ。土蔵造二階建、南北棟の切妻造本瓦葺。外壁は一階海鼠壁、二階白漆喰塗で、玄関脇となる東面に片開き窓と戸袋風の額縁を並べた飾窓を設ける。南面の戸口に両開き鉄扉を備えるなど堅牢なつくりで、重厚な表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012445"},{"id":"00012444","register_sub_id":"101","register_pk":"531768","name":"笹野家住宅離座敷","kana":"ささのけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県御坊市薗字新町731他","lat":33.88581111,"lng":135.1559,"geo_status":"db","era":"明治前期／昭和前期移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"30-235","desc":"旧屋敷地からの移築で、主屋の南西に廊下で接続する。平屋建、南北棟の入母屋造本瓦葺で、座敷二室を並べ、上手の十畳間は、床の間、床脇、付書院の座敷飾を構える。柱や長押に栂材を用い、端正な意匠をみせる明治前期和風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012444"},{"id":"00010494","register_sub_id":"101","register_pk":"199442","name":"佐竹家住宅主屋","kana":"さたけけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県御坊市御坊103","lat":33.888705,"lng":135.158182,"geo_status":"db","era":"明治中期／大正後期移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積150㎡","structure_material":"木造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0207","desc":"御坊寺内町の中心部、日高別院の北東側で東町通りに東面する、つし二階建。屋根は本瓦葺で正面に桟瓦葺の下屋を通す。一階床上部の正面は繊細な出格子を設け、二階に袖壁を付ける。平面は整型四間取で左に土間を設ける。寺内町の景観に寄与する間口の広い町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010494"},{"id":"00010495","register_sub_id":"101","register_pk":"199443","name":"佐竹家住宅離れ","kana":"さたけけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県御坊市御坊103","lat":33.888723,"lng":135.158018,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積62㎡","structure_material":"木造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0208","desc":"主屋角屋の北西に渡廊下を介して建ち、入母屋造本瓦葺で、東寄りに二階を持つ。一階は三室の座敷を並べ、八畳主室には書院付の床を設けて、部屋境に筬欄間を嵌める。二階座敷では数寄屋風を加味する。洗練された意匠になる離れで、山林業による繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010495"},{"id":"00013753","register_sub_id":"101","register_pk":"505313","name":"島影家住宅主屋","kana":"しまかげけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市紀三井寺1142","lat":34.18507222,"lng":135.18843611,"geo_status":"db","era":"昭和11年／昭和53年頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 300","desc":"熊野街道に東面。入母屋造桟瓦葺で正面板庇付。玄関の北に六畳、南に食堂を配し、西は六畳、八畳を南北に並べる。いずれも栂普請で、六畳は天井根太を面取の太い五平材、八畳は屋久杉と伝わる天井板を用いる。欄間や建具に意匠を凝らす上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013753"},{"id":"00005026","register_sub_id":"101","register_pk":"106016","name":"島村家住宅主屋","kana":"しまむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-1-6","lat":34.2152701,"lng":135.17065255,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積203㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"30 － 0077","desc":"木造２階建，寄棟造，桟瓦葺，外部モルタル塗の「あめりか屋」設計住宅。北面に玄関ポーチ，南面にパーゴラ付きテラスを設ける。外観は，ベイウィンドーや半円アーチの窓など洋風意匠を基本とするが，南面から東面にかけての１階を和風意匠とするのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005026"},{"id":"00005027","register_sub_id":"101","register_pk":"106017","name":"島村家住宅門及び塀","kana":"しまむらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市堀止東1-1-6","lat":34.21541348,"lng":135.17054438,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"門 コンクリート造、間口2.7m、塀 コンクリート造、延長55m","structure_material":"門 コンクリート造","registered":"2005.11.10(平成17.11.10)","register_no":"30 － 0078","desc":"敷地北辺の中央西寄りに，道路から退いた凹部に門を設ける。門の門口は１．８ｍで，木製の門扉を吊り，西側に潜口を開ける。塀は鉄筋コンクリート造，高さ２．０ｍで，下部鉄平石張，上部擬石タイル張，頂部笠石をモルタル塗に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005027"},{"id":"00004387","register_sub_id":"101","register_pk":"105377","name":"栖原角兵衛屋敷主屋","kana":"すはらかくべえやしきしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町栖原913-1","lat":34.04211691,"lng":135.16431477,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積311㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0066","desc":"敷地の南西に南面して建つ木造平屋建で，桁行５間梁行５間半。屋根は切妻造，本瓦葺で，表に本瓦葺の下屋庇を付ける。東が土間，床上は板間と８畳２室で，西に８畳座敷を突出させる。土間の東に落棟，北に炊事場の土間が付属する。建設年は棟札による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004387"},{"id":"00004388","register_sub_id":"101","register_pk":"105378","name":"栖原角兵衛屋敷土蔵","kana":"すはらかくべえやしきどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町栖原913-3","lat":34.04205959,"lng":135.164612,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0067","desc":"主屋の東方，敷地の南東角に位置する土蔵造２階建の東西棟で，屋根は切妻造，本瓦葺である。外壁は白漆喰塗で，腰を縦羽目板張とするが，南面の腰部を除き波形鉄板で覆っている。北面に戸口を設けて片引の土戸を建て込み，南面の１，２階に窓を開いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004388"},{"id":"00004389","register_sub_id":"101","register_pk":"105379","name":"栖原角兵衛屋敷土塀","kana":"すはらかくべえやしきどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町栖原913-1、3","lat":34.04205061,"lng":135.16413868,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長42m","structure_material":"土塀","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0068","desc":"敷地の南辺を限る土塀。主屋玄関前のもと表門から東方１８ｍと，西方折れ曲がり２４ｍが残る。石を詰めて土を塗り，白漆喰仕上とする。屋根は本瓦葺である。土蔵との取付部分は一段高くして虫籠窓風の窓を開き，腰部を土蔵と一連の縦羽目板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004389"},{"id":"00012606","register_sub_id":"101","register_pk":"367900","name":"瀬戸家住宅表門及び塀","kana":"せとけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、瓦葺、間口2.0m、北方袖塀付 塀 木造、瓦葺、延長20m","structure_material":"門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0244","desc":"敷地東南部を区切る門と塀。表門は主屋南側に東面して開く腕木門で、軒は吹寄せ垂木で繊細につくる一方、欄間は奇木を大胆に用いて飾る。塀は表門南側に接続する。真壁造、漆喰塗の腰縦板張で、屋根は一文字瓦を葺く。旧家の風格ある表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012606"},{"id":"00012602","register_sub_id":"101","register_pk":"367896","name":"瀬戸家住宅旧女中部屋及び風呂","kana":"せとけじゅうたくきゅうじょちゅうへやおよびふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0240","desc":"主屋後方の敷地北面東端に建つ。東西棟の切妻造桟瓦葺で、外壁漆喰塗の腰縦板張。内部は風呂、女中部屋、漬物部屋を並べ、風呂は腰タイル張で天井を張るが、女中部屋と漬物部屋は小屋組を現しとする。近代における旧家の生活の一端を伝える附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012602"},{"id":"00012604","register_sub_id":"101","register_pk":"367898","name":"瀬戸家住宅穀蔵","kana":"せとけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"天保13年（1842）／大正後期移築","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0242","desc":"敷地北面西寄りに建つ、もと小作米の保管庫。土蔵造二階建、東西棟の切妻造本瓦葺で、東面に戸口を設けて庇を付す。外壁漆喰塗の腰縦板張で、鉢巻を廻す。内部は上下階とも前後二室に分ける。小屋組は登梁。敷地内最古の建物で、大庄屋の有様を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012604"},{"id":"00012601","register_sub_id":"101","register_pk":"367895","name":"瀬戸家住宅座敷","kana":"せとけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"昭和前期／昭和35年頃増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0239","desc":"主屋西側に並んで建つ。入母屋造桟瓦葺平屋建で、南面東端に入母屋造の玄関を設け、東北隅に台所、西南隅に茶室を張出す。内部は12畳半の座敷と10畳の次の間からなる。良材を用いた端正なつくりで、重ね扇を透彫にした欄間など華やかな意匠をもつ客座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012601"},{"id":"00012600","register_sub_id":"101","register_pk":"367894","name":"瀬戸家住宅主屋","kana":"せとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0238","desc":"市東部の日高川西岸にある旧家の住宅で、主屋は敷地東寄りに南面して建つ。入母屋造桟瓦葺二階建で西側に角屋を出す。一階は東に土間、西に3列計7室を配する。二階は座敷ほか西南隅に洋室を設ける。良材を用いた丁寧なつくりで、近代和風住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012600"},{"id":"00012605","register_sub_id":"101","register_pk":"367899","name":"瀬戸家住宅西蔵","kana":"せとけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0243","desc":"敷地北西隅に建つ家財蔵。土蔵造二階建、南北棟の切妻造本瓦葺で、東面に戸口を設けて下屋を付す。外壁漆喰塗の腰縦板張で、鉢巻を廻す。窓庇の持送を繰形で飾り、小屋材まで鉋仕上とするなど丁寧につくる。敷地角にあって屋敷後方の構えの核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012605"},{"id":"00012603","register_sub_id":"101","register_pk":"367897","name":"瀬戸家住宅文庫蔵","kana":"せとけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市藤田町藤井2215","lat":33.906136,"lng":135.176163,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"30 － 0241","desc":"主屋後方の敷地北面中ほどに建つ。土蔵造二階建、南北棟の切妻造本瓦葺で、東面に戸口を設けて小庇を付す。外壁漆喰塗の腰縦板張で、軒に鉢巻を廻す。内部は上下階とも縦板張で、小屋組は登梁である。敷地背面の道路に面し、屋敷後方の構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012603"},{"id":"00009825","register_sub_id":"101","register_pk":"195654","name":"寒川家住宅石垣","kana":"そうがわけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95657358,"lng":135.46690299,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造、延長20m","structure_material":"石造","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0183","desc":"表門の西にのびる塀と、小門との間に築かれた石垣で、屋敷地の南西辺を区画する。緩やかに折れ曲がり、延長二〇メートルを測る。切石を腰ほどの高さに四段布積みし、上部に植栽を施す。要所に家紋に因む梅鉢を象った積み方を表し、外観に変化を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009825"},{"id":"00009822","register_sub_id":"101","register_pk":"195651","name":"寒川家住宅表門","kana":"そうがわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95660023,"lng":135.46721732,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、杉皮葺、間口4.0m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0180","desc":"敷地正面中央に構える間口三間の棟門で、中央間背面に控柱二本を立て、屋根は切妻造杉皮葺である。中央間を広くとって門口とし、東脇間を潜戸、西脇間を竪板壁とするが、開口はいずれも門扉を吊らず開放とする。風格ある大型の門で、表構えに格式を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009822"},{"id":"00009824","register_sub_id":"101","register_pk":"195653","name":"寒川家住宅小門","kana":"そうがわけじゅうたくこもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95662212,"lng":135.46681471,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口2.0m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0182","desc":"屋敷地の西辺、離れの南西側に開く小型の一間薬医門で、左右に土塀の袖塀を付ける。普段は使用されず、屋敷地の西側に位置する寒川神社で祭礼を行う際の出入りに使用する。全体に簡素な意匠となっているが、屋敷地と神社との関係性を示す門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009824"},{"id":"00009819","register_sub_id":"101","register_pk":"195648","name":"寒川家住宅主屋","kana":"そうがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95670683,"lng":135.4670993,"geo_status":"db","era":"嘉永3頃／昭和53改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0177","desc":"敷地中央に南面する。入母屋造茅葺で、桟瓦葺の下屋を廻す。東側の土間を後方に突出し、床上部は食違い四間取で、社家らしく大型の神棚を備える。部屋境には四本溝の差鴨居を入れるなど、古式を見せる。敷地内建物とあいまって山間地の農村景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009819"},{"id":"00009821","register_sub_id":"101","register_pk":"195650","name":"寒川家住宅土蔵","kana":"そうがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95663568,"lng":135.46727109,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0179","desc":"主屋の南東方に南北棟で建つ。桁行六・八メートル梁間五メートル、土蔵造二階建、切妻造、置屋根式の桟瓦葺で、西面を戸口として庇を付す。外壁は漆喰塗とし、腰を竪板張目板打ちとする。家財道具などを納める蔵で、屋敷地の景観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009821"},{"id":"00009820","register_sub_id":"101","register_pk":"195649","name":"寒川家住宅離れ","kana":"そうがわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.9566866,"lng":135.46693036,"geo_status":"db","era":"大正前期／昭和前期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0178","desc":"主屋西方に渡廊下を介して建つ。入母屋造桟瓦葺で四方に下屋を廻らし、壁上部を漆喰塗として格子窓を穿つ。内部は三室を東西に並べ、西端の八畳主室にトコと違棚、瀟洒な意匠の書院を設える。背面の浴室や便所は天井の意匠を凝らす。閑静な佇まいの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009820"},{"id":"00009823","register_sub_id":"101","register_pk":"195652","name":"寒川家住宅塀","kana":"そうがわけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡日高川町大字寒川273","lat":33.95659499,"lng":135.46715403,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、杉皮葺、総延長22m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"30 － 0181","desc":"表門の東西に折曲がりにのびる塀。東方が延長九・五メートル、西方が同一三メートルで、屋根は杉皮葺とする。水切の下部を竪板壁とし、上部は黒漆喰壁で、白漆喰の見切りを廻してアクセントとする。表門と同時期の建築で、ともに良質な表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009823"},{"id":"00004383","register_sub_id":"101","register_pk":"105373","name":"双青閣","kana":"そうせいかく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井字西青田806","lat":34.15526503,"lng":135.26109983,"geo_status":"db","era":"大正9／昭和43移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積144㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"30 － 0062","desc":"紀伊徳川家１５代頼倫が邸宅の一部として創建し，亀池中島に移築された。木造２階建，入母屋造，桟瓦葺で１階に庇がつく。方４間半の四周に縁が巡り，北西に玄関，東に階段を突出させる。１階に４室，２階に６室を配し，２階南西の１０畳を主座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004383"},{"id":"00015071","register_sub_id":"101","register_pk":"529349","name":"薗家住宅主屋","kana":"そのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.88613333,"lng":135.15568889,"geo_status":"db","era":"江戸末期／昭和28年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0362","desc":"御坊市の新町通りに位置する旧廻船業の主屋。通りに南面する平屋建入母屋造本瓦葺。中央東寄りを戸口とし、西は出格子構え、東は下見板張の洋風意匠。内部は田の字形平面で、南西隅を床構え付き座敷とする。建ちの低い町家で、地域の歴史的な景観の核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015071"},{"id":"00015077","register_sub_id":"101","register_pk":"529355","name":"薗家住宅片塀","kana":"そのけじゅうたくかたへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗字新町691","lat":33.88638889,"lng":135.15583889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0368","desc":"敷地東面の南土蔵から北面の東土蔵に至る、倉庫を兼ねる塀。北東部で西へ折れ曲がる梁間１間平屋建、招き屋根形の本瓦葺で、南端の桁行2間梁間1間半は漬物部屋とする。敷地側南寄りは吹放ちの作業場とし外周は竪板張とする。屋敷構えを印象づける長大な塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015077"},{"id":"00015074","register_sub_id":"101","register_pk":"529352","name":"薗家住宅西土蔵","kana":"そのけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.88642222,"lng":135.15554722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0365","desc":"敷地北辺の中央位置に南面して建つ、膳などの収納蔵。2階建切妻造平入本瓦葺。外壁は漆喰塗仕上で腰を竪板張とする。各階板敷で1階は東西２室に仕切り、2階は1室とする。窓が小さく閉鎖的な土蔵で、東土蔵と連続し敷地北辺に重厚な屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015074"},{"id":"00015072","register_sub_id":"101","register_pk":"529350","name":"薗家住宅人形蔵","kana":"そのけじゅうたくにんぎょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.88629167,"lng":135.1554,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0363","desc":"敷地西辺南寄に位置し、雛人形などを収納する蔵。東面して建つ、2階建切妻造平入本瓦葺。外壁は漆喰塗仕上で腰は竪板張とする。東面中央南寄りを戸口とし庇を付す。各階板敷とし、一階は二室、二階は一室。窓小さく閉鎖的で、敷地西方の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015072"},{"id":"00015073","register_sub_id":"101","register_pk":"529351","name":"薗家住宅離れ","kana":"そのけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.886325,"lng":135.15555833,"geo_status":"db","era":"昭和28年頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積25㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0364","desc":"敷地北辺の西寄りに南面して建つ離れ。二階建入母屋造妻入桟瓦葺で外壁は竪板張。一階南面には二階から下屋を葺降し、戸口前面を東西の通路状とする。各階は北に寄せて押入付六畳を配し、二階は北面窓から下川を望む。東の西土蔵に続き敷地北辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015073"},{"id":"00015075","register_sub_id":"101","register_pk":"529353","name":"薗家住宅東土蔵","kana":"そのけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.886425,"lng":135.15565833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造二階建、瓦葺、建築面積62㎡","structure_material":"土蔵造二階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0366","desc":"敷地北辺の中央部に南面して建つ家財蔵。2階建切妻造平入本瓦葺で、正面に本瓦葺の下屋を付す。外壁は漆喰塗仕上で軒まで塗込める。内部は各階板敷で、一階は東西2室とし、東上部を吹抜とする。外観閉鎖的な土蔵で、西土蔵とともに敷地北辺の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015075"},{"id":"00015076","register_sub_id":"101","register_pk":"529354","name":"薗家住宅南土蔵","kana":"そのけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市薗691","lat":33.88621667,"lng":135.15582222,"geo_status":"db","era":"大正後期／昭和28年頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造二階建、瓦葺、建築面積52㎡","structure_material":"土蔵造二階建","registered":"2024.08.15(令和6.08.15)","register_no":"30 - 0367","desc":"主屋北東に西面して建つ食器などの道具蔵。二階建切妻造妻入本瓦葺で西面南寄りを戸口とし、桟瓦葺の下屋を付す。外壁は漆喰塗仕上とし、腰はモルタル塗仕上。一階は東西二室の板敷とし、西室中央は上部吹抜とする。北に片塀が続き、敷地東辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015076"},{"id":"00014913","register_sub_id":"101","register_pk":"519173","name":"多井家住宅（旧吉田家住宅）茶室","kana":"たいけじゅうたく（きゅうよしだけじゅうたく）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中三丁目1101-1","lat":34.18960278,"lng":135.17065556,"geo_status":"db","era":"昭和24年／昭和40年代改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0348","desc":"敷地東半の庭に面して建ち、主屋南東に矩折れの渡廊下で繋がる茶室。寄棟造桟瓦葺、外壁は腰杉皮張、北と東に庇を廻し土縁とする。四畳半茶室と三畳の水屋からなり、東に床の間、貴人口、北に躙口を設ける。天井に網代や杉皮を用い、洗練された意匠の茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014913"},{"id":"00014912","register_sub_id":"101","register_pk":"519172","name":"多井家住宅主屋（旧吉田家住宅離れ）","kana":"たいけじゅうたくおもや（きゅうよしだけじゅうたはなれ）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中三丁目1101-1","lat":34.18970833,"lng":135.17058889,"geo_status":"db","era":"昭和24年／昭和30年代増築","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0347","desc":"和歌の浦に疎開した医院の旧離れ。敷地西側に南面する入母屋造の東西棟に北面突出部が付き、全体を桟瓦葺とする。西側の座敷は二間続きで床の間、床脇、付書院を設けて、長押を廻す。東側の座敷は下地窓風の丸窓など数寄屋風意匠とする戦後の良質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014912"},{"id":"00005654","register_sub_id":"101","register_pk":"106642","name":"高垣酒造土蔵","kana":"たかがきしゅぞうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.0782223,"lng":135.2802672,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0096","desc":"主屋の東方に南北棟で建つ。桁行３間，梁間２間，切妻造，桟瓦葺，平入の２階建土蔵で，西面北寄りに戸口を設け，南北妻面に各２箇所の小窓を開ける。外部は腰高の目板羽目とし，漆喰で軒下まで塗込める。窓小庇持ち送りの装飾など丁寧なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005654"},{"id":"00005657","register_sub_id":"101","register_pk":"106645","name":"高垣酒造塀","kana":"たかがきしゅぞうへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.07807632,"lng":135.28027501,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺、延長24m、門付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0099","desc":"主屋床上部南面中央に突出する４畳半の東南端に発し，座敷庭を取り囲むように建ち，土蔵東南端に取り付く。主屋寄りには瀟洒な腕木門を開く。切石を丁寧に積んだ基礎の上に建つ真壁造，桟瓦葺で，棟高２ｍ，腰を竪板張，上部の小壁を漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005657"},{"id":"00010038","register_sub_id":"101","register_pk":"196185","name":"豊島家住宅主屋","kana":"とよしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市清水字中栄226","lat":34.30831799,"lng":135.60083366,"geo_status":"db","era":"天明3","year":1783,"year_source":"db","year_min":1783,"year_max":1783,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積160㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"30 － 0189","desc":"旧高野街道に北面して建つ。右土間で、床上部は表側にマチノマなど三室、裏側を二室とする。一・二尺角の大黒柱や太い梁を架構し、成の高い差物でマチノマ周囲を固める。正面構えを太い格子や出格子で構成し、入口に摺揚戸を残すなど、橋本の町家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010038"},{"id":"00013169","register_sub_id":"101","register_pk":"368398","name":"豊原家住宅主屋","kana":"とよはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字滝1464","lat":34.32917778,"lng":135.50121389,"geo_status":"db","era":"江戸後期／平成31年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0272","desc":"葛城山脈山間集落に位置する農家。南斜面の狭隘な敷地東側に南面して建つ。入母屋造、茅葺で、小屋組は根太天井の上に土を載せる土天井とし、束踏上に棟束を立てる。床上部は整形四間取で、正面は奥行四尺の土庇とする。集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013169"},{"id":"00013170","register_sub_id":"101","register_pk":"368399","name":"豊原家住宅離座敷","kana":"とよはらけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字滝1464","lat":34.32915833,"lng":135.50109722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0273","desc":"主屋の西隣に南面して建つ座敷。平屋建、入母屋造平入、桟瓦葺で、四周に下屋を廻らす。八畳二間の正背面を縁とし、西側の八畳上手に床を設け、床脇は押入とする。部屋境は差鴨居を入れ、天井は棹縁天井とする。主屋とともに集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013170"},{"id":"00010878","register_sub_id":"101","register_pk":"201713","name":"なかがわ（旧中川家住宅）主屋","kana":"なかがわ（きゅうなかがわけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市御坊字東中筋106他","lat":33.888978,"lng":135.157885,"geo_status":"db","era":"昭和12／平成26改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積308㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"30 ‐ 0214","desc":"寺内町の通り沿いに建つ。入母屋屋根を重層させ、庇を廻らせた風格ある外観で、道側に座敷や洋風応接室を並べ、中庭を挟む庭園側に座敷四室などを配する。上下階とも南に廊下を通し開放する。林業家らしくヒノキの良材を多用し、和洋の意匠も上質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010878"},{"id":"00010880","register_sub_id":"101","register_pk":"201715","name":"なかがわ（旧中川家住宅）西蔵","kana":"なかがわ（きゅうなかがわけじゅうたく）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市御坊字東中筋106他","lat":33.888991,"lng":135.157749,"geo_status":"db","era":"昭和12／平成26改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"30 ‐ 0216","desc":"主屋の西側、玄関への斜路を挟む通り沿いに、南北棟で建つ。桁行五・六メートル梁間四・七メートル、土蔵造、切妻造本瓦葺で、南妻を戸口として瓦庇を付ける。外壁漆喰塗で鉢巻を廻らし、腰を花崗岩張とする。主屋と対峙して建ち、重厚な表構えを創る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010880"},{"id":"00010879","register_sub_id":"101","register_pk":"201714","name":"なかがわ（旧中川家住宅）東蔵","kana":"なかがわ（きゅうなかがわけじゅうたく）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市御坊字東中筋106他","lat":33.889032,"lng":135.158075,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"30 ‐ 0215","desc":"主屋東側の座敷部に前室を介して接続する。桁行五・八メートル梁間五・〇メートル、土蔵造二階建、切妻造本瓦葺で、前室側に扉を開く。外壁漆喰塗で鉢巻を廻らし、腰を洗出し仕上げとする。上下階とも南妻の窓に繰形付の庇を付す。庭空間を引立てる内蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010879"},{"id":"00001000","register_sub_id":"101","register_pk":"101990","name":"中筋家住宅主屋","kana":"なかすじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市禰宜316","lat":34.23045542,"lng":135.24979994,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積205㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0021","desc":"市内東部，紀ノ川南岸に広がる和佐地区にある。地区の大庄屋中筋家(住宅は重要文化財)から安政年間に分家した家で，主屋は大規模な平屋建，桟瓦葺の建物。せいの高い差鴨居，桜材の座敷縁などふんだんに良材を用いて高度な技能でつくられた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001000"},{"id":"00001003","register_sub_id":"101","register_pk":"101993","name":"中筋家住宅長屋門","kana":"なかすじけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市禰宜316","lat":34.23032372,"lng":135.24989756,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積50㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0024","desc":"屋敷地の東側，県道に面して建つ平屋建，桟瓦葺の長屋門で北に屋根を低くした貯蔵庫が附属する。道路側からみると長屋門と貯蔵庫が大壁造・腰下見板張りの一連の意匠になり，和佐地区で有数の規模を誇る屋敷構えにふさわしい姿をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001003"},{"id":"00001002","register_sub_id":"101","register_pk":"101992","name":"中筋家住宅西蔵","kana":"なかすじけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市禰宜316","lat":34.23056778,"lng":135.24970784,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，瓦葺，建築面積30㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0023","desc":"離れ座敷及び東蔵の西に隣接して，県道から入った道に北面して建つ。切妻造，平屋建，平入で，置屋根形式の土蔵で，道具蔵として使用されている。簡略な土蔵だが，腰板を張る外観は，離れ座敷及び東蔵と一連の意匠で，景観に配慮したつくりとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001002"},{"id":"00001001","register_sub_id":"101","register_pk":"101991","name":"中筋家住宅離れ座敷及び東蔵","kana":"なかすじけじゅうたくはなれざしきおよびひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市禰宜316","lat":34.23055949,"lng":135.24979994,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，瓦葺，建築面積62㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0022","desc":"中筋家の屋敷地は，和佐地区から海南市へ向かう県道と県道から西に入った道に面した南東の角地にある。離れ座敷及び東蔵は，県道から入る道に北面して建つ。西側に６畳間２室をとり，東を什器蔵とする。広大な屋敷構えの主要な構成要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001001"},{"id":"00001004","register_sub_id":"101","register_pk":"101994","name":"中筋家住宅便益棟","kana":"なかすじけじゅうたくべんえきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市禰宜316","lat":34.23046371,"lng":135.24994269,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積11㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0025","desc":"長屋門の北に建つ切妻造，平屋建，桟瓦葺の建物で，長屋門に附属する貯蔵庫との間に勝手口を設ける。内部は便所・風呂場・物置等からなる。外観の意匠を長屋門・同貯蔵庫とあわせ，屋根を貯蔵庫よりわずかに低くして景観上効果的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001004"},{"id":"00007529","register_sub_id":"101","register_pk":"108511","name":"長多家住宅主屋","kana":"ながたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市井ノ口119-2","lat":34.23641126,"lng":135.25070378,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0139","desc":"敷地中央に南面して建つ。東西棟の切妻造本瓦葺で、桟瓦葺錣屋根の下屋庇をまわし、西に落棟で寄棟造桟瓦葺の座敷部を付ける。東にもと土間、西に居室を田の字型に配する。座敷部は十畳で、トコと付書院を構え仏壇を置く。伝統的な形態を受け継ぐ近代農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007529"},{"id":"00007530","register_sub_id":"101","register_pk":"108512","name":"長多家住宅土蔵","kana":"ながたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市井ノ口119-2","lat":34.236523,"lng":135.25076226,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0140","desc":"主屋の北側に建つ土蔵造２階建。桁行１１ｍ梁間４．１ｍ、東西棟の切妻造本瓦葺で、東寄り桁行３．２ｍの棟を低くし、さらに東面に下屋庇を付ける。屋根形態の違いに合わせて、軒まわりの仕様や腰竪板壁の高さを違えて、リズム感のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007530"},{"id":"00007532","register_sub_id":"101","register_pk":"108514","name":"長多家住宅土塀","kana":"ながたけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市井ノ口119-2","lat":34.23647485,"lng":135.25059101,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長66m","structure_material":"土塀","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0142","desc":"門長屋から西に延び、北に折れて敷地を東西に分け、土蔵からも西へ延びる。総延長６６ｍ。紀州の青石といわれる緑泥片岩を１．２ｍの高さに積み上げ、その上に１．３ｍ高の土塀を造る。屋根は桟瓦葺。屋敷構えと農地が一体となって、豊かな農村景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007532"},{"id":"00007531","register_sub_id":"101","register_pk":"108513","name":"長多家住宅門長屋","kana":"ながたけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市井ノ口119-2","lat":34.236237,"lng":135.25070809,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0141","desc":"敷地南側の通りから少し入った位置に建つ。桁行２３ｍ梁間５．１ｍ、東西棟の入母屋造本瓦葺。中央西寄りに間口３．０ｍの門口を設ける。切石上に建ち、腰下見板張で黒漆喰仕上げとし、西寄りに出格子窓を設ける。腰板のすぐ上に通る白漆喰の線が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007531"},{"id":"00009662","register_sub_id":"101","register_pk":"194658","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市七山字星子1259","lat":34.19805719,"lng":135.31322373,"geo_status":"db","era":"明治前期／明治後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"30 － 0175","desc":"田園地帯の敷地に南面し、木造平屋建、入母屋造桟瓦葺で、下屋を廻らす。内部は東寄りを土間、床上部を整型四間取とし、南側にザシキ・シモノマを配する。小屋は棟束に登梁を鼻栓差とする。土間寄付きの部屋境を半間ずらすなど、当地方の民家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009662"},{"id":"00013319","register_sub_id":"101","register_pk":"366308","name":"橋本太次兵衛家住宅新座敷","kana":"はしもとたじべえけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原256","lat":33.903175,"lng":135.16234722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造二階建、瓦葺、建築面積49㎡","structure_material":"木造二階建","registered":"2020.04.03(令和2.04.03)","register_no":"30 － 0280","desc":"旧熊野街道に東面する敷地の中央北寄りに東面して建つ。木造二階建、寄棟造桟瓦葺で、正面南寄りに起り付屋根の玄関を突き出す。小屋組は梁間二間の和小屋とする。一、二階とも八畳の床の間を配す。比較的小規模で建ちが高く、良材を用いた明治後期の新座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013319"},{"id":"00012784","register_sub_id":"101","register_pk":"367687","name":"畑田家住宅主屋","kana":"はただけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市船尾字中濱215-67","lat":34.16301083,"lng":135.19817389,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 250","desc":"市街地北西部の船尾にある漆器業者の旧宅。主屋は街路に東面して建つ入母屋造桟瓦葺の総二階建。軒を出桁造、外壁を黒漆喰塗とし、二階を大壁とするなど重厚に仕上げる。内部は一階に居室、二階に座敷を設ける。近代住宅地の景観の核をなす上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012784"},{"id":"00012785","register_sub_id":"101","register_pk":"367688","name":"畑田家住宅門及び塀","kana":"はただけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市船尾字中濱215-67","lat":34.16301083,"lng":135.19817389,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門 コンクリート造、間口1.5m 塀 コンクリート造、総延長26m","structure_material":"門 コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 251","desc":"敷地南半の庭の周囲を区切る塀と門。塀は高さ1・6メートルのコンクリート造で、頂部を繰形付のモルタル洗出し仕上とする。門は東面塀の北端を後退させ、モルタル洗出し仕上の門柱を間口1・5メートルで立てる。角地にあって近代的な屋敷構えを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012785"},{"id":"00009202","register_sub_id":"101","register_pk":"164755","name":"平松家住宅主屋","kana":"ひらまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市川辺603","lat":34.25699337,"lng":135.26542546,"geo_status":"db","era":"安政3年(1856)","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"上方街道に西面する敷地中央に建つ。木造つし2階建、建築面積222平方メートル、入母屋造本瓦葺で下屋を廻らす。正面中央に入母屋造の式台玄関を突出させ、北西には仏間と茶室を設け、北側水路に迫り出す。重厚な構えの住宅で、優れた農村景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009202"},{"id":"00009203","register_sub_id":"101","register_pk":"164756","name":"平松家住宅長屋門","kana":"ひらまつけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市川辺603","lat":34.25698575,"lng":135.26520274,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地西辺に建ち、桁行18.7メートル梁間4メートル、入母屋造本瓦葺。中央南寄りに半間ひかえて門を開き、ケヤキ1枚板の板戸を両開きに吊り、北脇に潜戸を吊る。外壁は腰を簓子下見板張とし、土壁に武者窓を穿つ。木太く、重厚な構えを見せる長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009203"},{"id":"00009216","register_sub_id":"101","register_pk":"164769","name":"福田家住宅石垣及び土塀","kana":"ふくだけじゅうたくいしがきおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59128083,"lng":135.61142542,"geo_status":"db","era":"江戸末期／明治33年・大正3年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石垣 石造、総延長154m、石段付 土塀 土塀、瓦葺、総延長63m","structure_material":"石垣 石造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地正背面の石垣と正面の土塀である。正面石垣は高さ約4メートル総延長98メートル、反りをもたせた布積で精緻に積む。土塀は総延長63メートルで、漆喰仕上げ、桟瓦葺。背面石垣は延長56メートルの布積である。長大な石垣と土塀が城郭のような趣を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009216"},{"id":"00009208","register_sub_id":"101","register_pk":"164761","name":"福田家住宅内塀","kana":"ふくだけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.27545674,"lng":135.27913862,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、総延長13m、門付","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"表門から主屋に至る通路西辺に南北棟で建ち、総延長13メートル、切妻造桟瓦葺で、中央北寄りに腕木門を、両端に木戸を開く。各柱間に窓を穿ち、塀は真壁で、通路側を黒漆喰塗、腰を下見板張とし、内庭側を白壁とする。品格のある庭空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009208"},{"id":"00009206","register_sub_id":"101","register_pk":"164759","name":"福田家住宅北蔵","kana":"ふくだけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.27570991,"lng":135.27905677,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北辺に東西棟で建つ。桁行7.9メートル梁行4.6メートル、土蔵造2階建、切妻造妻入本瓦葺。1階東面は海鼠壁、北面と西面は竪板張とする。2階北面に2箇所、西面に1箇所の窓を穿ち、庇の持送りに漆喰で装飾的な繰形を見せる、丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009206"},{"id":"00009205","register_sub_id":"101","register_pk":"164758","name":"福田家住宅米蔵及び納屋","kana":"ふくだけじゅうたくこめぐらおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.2755186,"lng":135.2791943,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建一部木造平屋建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建一部木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地東辺に沿って南北棟で建つ。建築面積74平方メートル、土蔵造2階建1部木造平屋建、切妻造本瓦及び桟瓦葺である。南から米蔵、納屋、風呂を配する。米蔵は腰をモルタル洗出しとし、納屋は腰に竪板を張る。主屋に向かう通路に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009205"},{"id":"00009210","register_sub_id":"101","register_pk":"164763","name":"福田家住宅主屋","kana":"ふくだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59132509,"lng":135.6115601,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"石垣を築いた敷地中央に南面する。桁行13.8メートル梁間8.7メートル、木造平屋建、入母屋造桟瓦葺で、北東隅に炊事場を張出し、床上部は2列に6室を配する。前列下手に土間付の玄関をおき、上手の縁は軒を深く出すなど、紀南地方の民家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009210"},{"id":"00009204","register_sub_id":"101","register_pk":"164757","name":"福田家住宅主屋","kana":"ふくだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.27560427,"lng":135.27911054,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に南面して建つ。木造平屋建、桁行15.1メートル梁間10メートル、入母屋造本瓦葺で、下屋を廻らす。内部は東が土間で、床上は整型4間取の1部をさらに分割し、前列上間にトコ.棚を備える。南面中央には入母屋造の式台玄関を設け、風格を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009204"},{"id":"00009214","register_sub_id":"101","register_pk":"164767","name":"福田家住宅正門","kana":"ふくだけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.5912223,"lng":135.61151965,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋正面の、石垣と土塀に挟まれた石段上部に開かれた門である。間口2.4メートルの一間腕木門で、切妻造桟瓦葺である。親柱間に方立を立ててケヤキ1枚板の板戸を両開きに吊り、上部に菱格子欄間を飾る。小規模ながら、風格を備えた正門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009214"},{"id":"00009209","register_sub_id":"101","register_pk":"164762","name":"福田家住宅土塀","kana":"ふくだけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.27558107,"lng":135.27899495,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土塀、瓦葺、総延長42m","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地西辺の道路に沿って建ち、南北両端を矩折れとする。延長41.5メートル高さ約2.5メートル、切妻造桟瓦葺。基礎は精緻な間知石積とし、外壁はモルタル洗出し、軒先は漆喰塗とする。重厚な姿が落ち着きのある旧家の屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009209"},{"id":"00009212","register_sub_id":"101","register_pk":"164765","name":"福田家住宅納屋","kana":"ふくだけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59132579,"lng":135.61174237,"geo_status":"db","era":"明治11年／明治45年・大正9年改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積52㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の東北側に建ち、桁行8.2メートル梁間3.6メートル、木造平屋1部2階建、切妻造桟瓦葺で3方に下屋を廻らす。外観は腰高に竪板を張り、上部は真壁の漆喰塗とする。1階は南半の4室を物入など、北半は1室の農具置場とし、2階は居室にも使用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009212"},{"id":"00009215","register_sub_id":"101","register_pk":"164768","name":"福田家住宅西門","kana":"ふくだけじゅうたくにしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59134508,"lng":135.61132834,"geo_status":"db","era":"大正2年頃／昭和前期改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"離座敷南西側の石段上部に西面して建つ。間口1.7メートルの一間腕木門で、南面に袖塀を矩折れに設けてＬ字形平面を呈し、屋根は切妻造桟瓦葺である。ケヤキ板の板戸を両開きに吊り、上部の板欄間に竹や菊花などを透かす。正門とともに屋敷構えを引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009215"},{"id":"00009211","register_sub_id":"101","register_pk":"164764","name":"福田家住宅離座敷","kana":"ふくだけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59137934,"lng":135.61141781,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の西側に、渡廊下を介して建つ。建築面積42平方メートル、木造平屋建、入母屋造及び切妻造、桟瓦葺である。6畳主室はトコ.棚.付書院を備え、南東面を開放して縁を廻らす。主要部材にケヤキを使用し、木柄が細く、軽妙な印象の離座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009211"},{"id":"00009213","register_sub_id":"101","register_pk":"164766","name":"福田家住宅風呂及び便所","kana":"ふくだけじゅうたくふろおよびべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町佐本東栗垣内115","lat":33.59125228,"lng":135.61169383,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"主屋の東側、納屋南面に建ち、桁行4.7メートル梁間4.5メートル、木造平屋建、入母屋造桟瓦葺である。南半に大小の便所5基、北半に脱衣場と風呂場を配し、外壁は板壁と黄土壁とする。丁寧なつくりになる建物で、往時の生活様式と屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009213"},{"id":"00009207","register_sub_id":"101","register_pk":"164760","name":"福田家住宅門","kana":"ふくだけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県岩出市山318","lat":34.27538535,"lng":135.27916955,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の南辺中央に東西棟で建つ。間口2.1メートルの一間薬医門、切妻造桟瓦葺で、東西に落棟として切妻造桟瓦葺の袖を付け、西袖に潜戸を開く。本柱に冠木を架け渡し、ケヤキ1枚板を用いた板戸を両開きとする。格式のある屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009207"},{"id":"00010225","register_sub_id":"101","register_pk":"198058","name":"堀河屋又兵衛家住宅主屋","kana":"ほりかわやまたべえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市御坊85","lat":33.887167,"lng":135.157523,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積189㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0192","desc":"日高御坊の寺内町中心部に所在し、別院裏の通りに西面して建ち、本瓦葺とする。正面に出格子をたて、軒先に当地でオダレと呼ぶ幕板を設けて地方的特色を備える。内部は前後二列で後列北を座敷とする。建ちが低く古様を示す町家で、寺内町の景観形成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010225"},{"id":"00010226","register_sub_id":"101","register_pk":"198059","name":"堀河屋又兵衛家住宅土蔵","kana":"ほりかわやまたべえけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市御坊85","lat":33.887254,"lng":135.157428,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0193","desc":"主屋の北側に接道して東西棟で建つ、切妻造二階建の土蔵。基礎は花崗岩積で、西面は一階を竪板張、二階を漆喰塗とする。小屋組は折置組の登梁とし、屋根には本瓦を葺いて緩やかな起りをつける。主屋とともに、寺内町の通りの歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010226"},{"id":"00004289","register_sub_id":"101","register_pk":"105279","name":"前田家住宅新書院","kana":"まえだけじゅうたくしんしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉392-1","lat":34.30499287,"lng":135.55574,"geo_status":"db","era":"大正5／昭和30曳家","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0060","desc":"中書院の南に位置する。東を入母屋造，西を切妻造とした東西棟，桟瓦葺，平屋建の客用座敷で，内部は西から６畳の式台玄関，１０畳，床・棚・付書院を備えた１２畳半座敷を並べ，東南２面の下屋に半間の板縁を廻す。式台・床等，格の高さを示すつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004289"},{"id":"00004290","register_sub_id":"101","register_pk":"105280","name":"前田家住宅土蔵","kana":"まえだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉392-1","lat":34.30486327,"lng":135.55570363,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0061","desc":"敷地南端に北面し，東西棟で建つ。桁行７間梁間３間，切妻造，本瓦葺の２階建土蔵で，北面に半間の土庇を差し掛け，２戸口を設ける。内部は２室とし，東３間分が什器蔵，西４間分の１階が米蔵，２階が衣裳蔵で，現在は一部をギャラリーとして活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004290"},{"id":"00004288","register_sub_id":"101","register_pk":"105278","name":"前田家住宅中書院","kana":"まえだけじゅうたくなかしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉392-1","lat":34.305058,"lng":135.55577425,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0059","desc":"主屋の東南方に位置し，東西棟で建つ。桁行３間半梁間２間，入母屋造，桟瓦葺の平屋建で，四面に半間の下屋庇を廻す。内部は８畳と床付き６畳の２室構成になり，南面下屋は押入と床，他３面は板縁とし，主屋と渡廊下で繋がる。良材を用いた上質な離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004288"},{"id":"00013171","register_sub_id":"101","register_pk":"368400","name":"的場家住宅主屋","kana":"まとばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷1046","lat":34.34917222,"lng":135.49208056,"geo_status":"db","era":"文化2年（1805）／平成18年改修","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、茅葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0274","desc":"細長い敷地中央に南西向きに建つ農家。入母屋造平入茅葺で、南隅に桟瓦葺の下屋を出す。床上部は整形四間取で、正面は土縁とする。部屋境は差鴨居を入れ柱を省略するが、三本溝の差鴨居など古式を見せる。建築年代が明らかで紀北地域の近世農家の指標となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013171"},{"id":"00013173","register_sub_id":"101","register_pk":"368402","name":"的場家住宅土蔵","kana":"まとばけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷1046","lat":34.34925833,"lng":135.49197778,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0276","desc":"主屋の北西に、南東を向いて建つ。北東の土蔵部は土蔵造二階建、切妻造平入で正面に下屋を下す。南西の居室部は木造平屋建、入母屋造桟瓦葺。土蔵部の小屋組は桁行中央に梁を渡し、束立で棟木と母屋を支える。主屋とともに集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013173"},{"id":"00013172","register_sub_id":"101","register_pk":null,"name":"的場家住宅離れ","kana":"まとばけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷1046","lat":34.34911389,"lng":135.49216667,"geo_status":"db","era":"大正後期／平成18年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0275","desc":"主屋の南東に隣接して建つ離れ。木造二階建、入母屋造、桟瓦葺で、三方に下屋を廻らす。一階は台所と座敷、二階は八畳間二室からなる。台所はかつては土間の作業場であったという。主屋とともに集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013172"},{"id":"00005348","register_sub_id":"101","register_pk":"106336","name":"三尾家住宅主屋","kana":"みおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-17","lat":34.21413559,"lng":135.1695441,"geo_status":"db","era":"天保12","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0082","desc":"市街地を南北に貫く国道４２号の近傍に建つ。間口約１０ｍの切妻造，本瓦葺，平入とし，１階に格子窓を配し，漆喰を塗込めた２階正面には虫籠窓を左右対称に穿つ端正なつくり。市内に残る数少ない町家建築の一つで，歴史的街路景観を形成する貴重な要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005348"},{"id":"00005349","register_sub_id":"101","register_pk":"106337","name":"三尾家住宅土蔵","kana":"みおけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市堀止西1-17","lat":34.21402227,"lng":135.16955752,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0083","desc":"主屋の背後に南面して建ち，５．１ｍ四方の規模を有する。切妻造，本瓦葺，妻入の土蔵で，切石を基礎とし，四周に水切付の胴蛇腹と鉢巻を廻らす。正面の腰はモルタル塗洗出しとし，その他の面は杉板張とする。敷地の南西に位置し，屋敷構を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005349"},{"id":"00000223","register_sub_id":"101","register_pk":"101213","name":"御前家住宅主屋","kana":"みさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市茶屋ノ丁1","lat":34.22297977,"lng":135.16862865,"geo_status":"db","era":"昭和10～13","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積185㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"30 － 0002","desc":"和歌山城に程近い市街地に建つ木造の住宅。平屋建だが庇屋根を廻して屋根を２重にする外観や丸太を用いる内装に数寄屋造りの影響がみられることや洋風の応接間を持つこと等に、昭和初期に大規模邸宅にみられる特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000223"},{"id":"00000224","register_sub_id":"101","register_pk":"101214","name":"御前家住宅台所棟","kana":"みさきけじゅうたくだいどころとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市茶屋ノ丁1","lat":34.22306324,"lng":135.16857005,"geo_status":"db","era":"昭和10～13","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積89㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"30 － 0003","desc":"主屋と同時期にあわせて建設された建物で、食堂・炊事場等からなる。平屋建、寄棟造の簡素なつくりで、数寄屋造風の豪壮な主屋と好対照をなしている。接客部と台所棟を別棟で建てる江戸時代の武家住宅の系譜を引く昭和初期の邸宅の様子を示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000224"},{"id":"00000225","register_sub_id":"101","register_pk":"101215","name":"御前家住宅土蔵","kana":"みさきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市茶屋ノ丁1","lat":34.22305185,"lng":135.16848463,"geo_status":"db","era":"昭和10～13","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積33㎡","structure_material":"土蔵造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"30 － 0004","desc":"主屋・台所棟と同時期にあわせて建設された２階建の土蔵で、裏通りに面して妻を見せる。和歌山城下の、城に近い位置にある上級武家住宅の系譜を引く民家の屋敷構えを構成する主要な建物で、この地の往事の様子を知る手がかりとなる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000225"},{"id":"00003905","register_sub_id":"101","register_pk":"104895","name":"みそや別館上蔵及び離れ座敷","kana":"みそやべっかんかみぐらおよびはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市橋本一丁目1006","lat":34.31668005,"lng":135.6120137,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"30 － 0052","desc":"主屋の背後に建つ。上蔵は２階建，土蔵造，切妻造，妻入の道具蔵で，南に蔵前を設け，軒に大型の鉢巻を廻し戸口に屋号を塗り込んだ観音開土戸を釣り込む。西の離れ座敷は床付の数寄屋風座敷と仏間からなり，両建物を巧みに一体化して屋敷背後の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003905"},{"id":"00003906","register_sub_id":"101","register_pk":"104896","name":"みそや別館下蔵","kana":"みそやべっかんしもぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本一丁目1006","lat":34.31669426,"lng":135.61190974,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"30 － 0053","desc":"離れ座敷西方に独立して建つ。土蔵造，２階建，切妻造，平入で，南面戸前に庇を付ける。内部は１階全面土間で，味噌蔵または道具蔵として使用された。小規模で簡素な土蔵だが，開口部の入念な塗り廻しや垂木を波形に塗り込めた軒廻りなど丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003906"},{"id":"00003904","register_sub_id":"101","register_pk":"104894","name":"みそや別館主屋","kana":"みそやべっかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市橋本一丁目1006","lat":34.31656301,"lng":135.61194149,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"30 － 0051","desc":"伊勢街道に南面する呉服店の主屋。２階建，切妻造，桟瓦葺で，屋根をコの字型にかけ西半は中庭をとって表屋造風となる。２階には瀟洒な床棚を構え，長押を省略した数寄屋風の座敷を配し，緩い起り屋根，虫籠窓風の表２階の窓等，京風町家の外観を巧みに造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003904"},{"id":"00011788","register_sub_id":"101","register_pk":"210804","name":"宮﨑家住宅主屋","kana":"みやざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市加太1388","lat":34.275717,"lng":135.07603,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0226","desc":"桁行六間半、梁間四間の周囲に下屋庇を出す総二階建の入母屋造本瓦葺で、正面右に土間を取り、床上部は四間取。一階は腰板張、上部黒漆喰塗で、二階開口部には銅板折戸を付ける。当初は二階で綿布業の作業を行なっていたと伝え、地域の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011788"},{"id":"00011789","register_sub_id":"101","register_pk":"210805","name":"宮﨑家住宅土蔵","kana":"みやざきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市加太1388","lat":34.275849,"lng":135.07599,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0227","desc":"主屋背面側、敷地の西北隅に建つ。桁行五・四メートル、梁間三・七メートル、切妻造本瓦葺の土蔵造二階建で、東妻面に扉口を開く。基礎を高く積み、外壁は腰縦板張、上部漆喰塗で軒まで塗込める。内部は一・二階とも一室とし、一階南面、二階東面に窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011789"},{"id":"00011790","register_sub_id":"101","register_pk":"210806","name":"宮﨑家住宅長屋門","kana":"みやざきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市加太1388","lat":34.275819,"lng":135.076074,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0228","desc":"淡路街道に面し、主屋背面側に直交して建つ。切妻造桟瓦葺の平屋建で、桁行五間、梁間二間の規模を有し、中央部に一間幅の門口を開く。扉口の北には土間より入る六畳間、南には物置を設ける。港町のかつての景観を今に伝える長屋門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011790"},{"id":"00015213","register_sub_id":"101","register_pk":"530637","name":"宮田家住宅主屋","kana":"みやたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市紀三井寺1094他","lat":34.18373611,"lng":135.18856111,"geo_status":"db","era":"寛政8年(1796)／明治中期増築、昭和30年代改修","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0374","desc":"紀三井寺南方に位置するかつての米穀商の主屋。熊野街道沿いの角地に西面して建つ、つし二階建入母屋造妻入本瓦葺で正側面に下屋を付す。内部は玄関土間の東に２列５室を配し、南東に角座敷を延ばす。格子構えの建ちの低い妻入町家が街道沿いの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015213"},{"id":"00013623","register_sub_id":"101","register_pk":"504992","name":"向井家住宅表門及び袖塀","kana":"むかいけじゅうたくおもてもんおよびそでべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市加太字北仲丁1394-1","lat":34.27564167,"lng":135.07584167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門 木造、瓦葺、間口1.9m、袖塀 木造、瓦葺、総延長4.6m","structure_material":"表門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0293","desc":"敷地の南面中央、旧淡島街道に面して建つ一間腕木門で、切妻造の桟瓦葺である。東西に桟瓦葺の袖塀が延びる。門柱は角柱で、絵様、繰形を施した腕木の上に扁平な冠木を載せ、背面側腕木は控柱で受ける。軒は一軒疎垂木である。軒の出大きく質実な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013623"},{"id":"00013621","register_sub_id":"101","register_pk":"504990","name":"向井家住宅主屋","kana":"むかいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1394","lat":34.27578333,"lng":135.07585278,"geo_status":"db","era":"万延元年(1860)／平成12年改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0291","desc":"旧淡島街道に南面する葛城修験に関わりが深い旧家である。入母屋造本瓦葺で下屋も本瓦葺とする。整形四間取の表十畳二室は正面を出格子とし、吹放しの下屋が広い軒下をなす。居室は全て大引天井で、差物を用いた堅牢な構造が特徴的な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013621"},{"id":"00013622","register_sub_id":"101","register_pk":"504991","name":"向井家住宅土蔵","kana":"むかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1394","lat":34.27585278,"lng":135.07578889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積18㎡","structure_material":"土蔵造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0292","desc":"主屋の北背後西寄りに建つ家財蔵である。東西棟で切妻造の本瓦葺とする。外壁は白漆喰塗で螻羽に母屋鼻を塗込で見せ、腰は縦羽目板張とする。南面中央に戸口を設け、瓦葺庇の腕木に漆喰塗の大振りな持送がつく。主屋と並び西からの添景をなす建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013622"},{"id":"00013624","register_sub_id":"101","register_pk":"504993","name":"向井家住宅塀","kana":"むかいけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市加太字北仲丁1394-1","lat":34.27561389,"lng":135.07578889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、瓦葺、延長8.2m","structure_material":"コンクリート造","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0294","desc":"敷地の南正面西半、表門の袖塀に続く塀である。基礎はモルタル洗出し仕上で、コンクリート壁の上部を墨塗とし、腰の縦羽目板張との間を白帯に塗る。上部に桟瓦を葺く。敷地内側に控えを取る。表門袖塀と意匠を揃え、旧街道沿いの重厚な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013624"},{"id":"00013760","register_sub_id":"101","register_pk":"505319","name":"森家住宅隠居屋","kana":"もりけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県日高郡印南町大字崎ノ原字横畑275-4他","lat":33.86998889,"lng":135.29063611,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 307","desc":"主屋の西に接続する。入母屋造の南北棟で、東面北端から洗面所と風呂場を突出して、主屋との間に中庭をとる。南端が座敷で北面に床、棚、押入を造り、南に広縁を付ける。北に一〇畳居室と小台所を並べ、東に縁を通す。屋根の青色釉薬瓦が通りからも目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013760"},{"id":"00013759","register_sub_id":"101","register_pk":"505317","name":"森家住宅主屋","kana":"もりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県日高郡印南町大字崎ノ原字横畑275-4他","lat":33.86999167,"lng":135.29073889,"geo_status":"db","era":"大正5年／昭和45年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 306","desc":"国道四二五号に南面する。入母屋造桟瓦葺で正面を出桁造とし軒を低く葺下ろす。東を板張の旧土間と台所とし、床上部は南列が八畳と四畳の続き間座敷で、仏壇、床、押入を造り、南に広縁を通す。北列は居室二室。低い軒や間取等は紀州の山間農家の伝統を継承。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013759"},{"id":"00013625","register_sub_id":"101","register_pk":"504994","name":"山﨑家住宅主屋","kana":"やまさきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市粉河853-3","lat":34.27148611,"lng":135.40511389,"geo_status":"db","era":"大正6年／平成25年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積462㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0295","desc":"ＪＲ粉河駅北に敷地を構える。入母屋造の南妻に入母屋造玄関を突出する。東に折上格天井の大広間棟、西に中庭を介して家政棟が接続する。続き間座敷が四組あり趣を異にして上質な造作を見せる。二階八畳は傘天井で飾る。良材を駆使した近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013625"},{"id":"00013627","register_sub_id":"101","register_pk":"504996","name":"山﨑家住宅北蔵","kana":"やまさきけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市粉河853-3","lat":34.27165278,"lng":135.40506111,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積124㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0297","desc":"敷地の北西隅に建つ東西棟で寄棟造の桟瓦葺とする。外壁は鉢巻まで鉄板で張る。一階は独立した東西二室の間に漆喰塗大壁仕上の中室を設ける。東室から上がる二階は間仕切なしの一室とする。小屋組は登梁に束立で棟木と母屋を受け、緩勾配の屋根をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013627"},{"id":"00013628","register_sub_id":"101","register_pk":"504997","name":"山﨑家住宅塀","kana":"やまさきけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市粉河字東鳥居853-3","lat":34.27149444,"lng":135.40534722,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、一部瓦葺、延長130m","structure_material":"煉瓦造","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0298","desc":"敷地四面に設けた煉瓦塀である。南正面は中央に門口、西端に通用口を開いて上部に桟瓦を葺く。西面の隣地境は防火のため高塀とする。東面はモルタル塗笠木を掲げ一部の外側に柱形を見せる。北土蔵の両側は壁面をモルタル塗とする。敷地外周の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013628"},{"id":"00013626","register_sub_id":"101","register_pk":"504995","name":"山﨑家住宅南蔵","kana":"やまさきけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市粉河853-3","lat":34.27131389,"lng":135.40533611,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0296","desc":"敷地の南東隅に建つ南北棟、切妻造の本瓦葺とする。外壁は縦板張で鉢巻を白漆喰塗とする。西面中央に石階段を設けて戸口に土戸を片引に建込み、桟瓦葺の庇をつける。小屋組は野物の梁に束立で棟木と母屋を受ける。建ちが高く南からの景観の中心要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013626"},{"id":"00006395","register_sub_id":"101","register_pk":"107378","name":"山本家住宅赤倉","kana":"やまもとけじゅうたくあかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.160172,"lng":135.25975,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0127","desc":"隠居所の北側縁から廊下を介して続く木造２階建。１階は方３間、２階は方２間で、寄棟造桟瓦葺とする。１階屋根には千鳥破風を飾る。外壁木部の赤ペンキ塗から赤倉の称がある。内部は１、２階とも１室で、木部は水色ペンキ塗。独特の外観で親しまれる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006395"},{"id":"00006393","register_sub_id":"101","register_pk":"107376","name":"山本家住宅石塀","kana":"やまもとけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15983678,"lng":135.26011601,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"石造、延長18m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0129","desc":"敷地南面の東半に設けられ、主屋座敷部の庭園と国道を画す。門の袖塀南端から延長１８ｍ余。石材は緑泥片岩系の和歌山産青石で、人頭大の石を乱石積とする。基底幅は４０ｃｍとし、高さ１．８ｍで、上端を笠木形に造る。街路景観に独特の雰囲気を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006393"}];
